export function filterableFields(schema) {
    if (!schema || typeof schema !== "object" || !Array.isArray(schema.fields)) {
        return [];
    }
    return schema.fields
        .filter(
            (field) =>
                field &&
                typeof field === "object" &&
                field.filterable === true &&
                typeof field.key === "string" &&
                isMetadataKey(field.key.trim()) &&
                typeof field.label === "string" &&
                Array.isArray(field.operators),
        )
        .sort((left, right) => numeric(left.position) - numeric(right.position) || left.key.localeCompare(right.key));
}

export function filterControls(field) {
    const operators = new Set(field.operators);
    if (field.type === "number") {
        const controls = [];
        if (operators.has("gte")) {
            controls.push({ operator: "gte", param: filterParam(field.key, "gte"), valueType: "number" });
        }
        if (operators.has("lte")) {
            controls.push({ operator: "lte", param: filterParam(field.key, "lte"), valueType: "number" });
        }
        if (controls.length === 0 && operators.has("eq")) {
            controls.push({ operator: "eq", param: filterParam(field.key, "eq"), valueType: "number" });
        }
        return controls;
    }
    if (operators.has("eq")) {
        return [
            {
                operator: "eq",
                param: filterParam(field.key, "eq"),
                valueType: field.type === "boolean" ? "boolean" : "string",
            },
        ];
    }
    return [];
}

export function numericRange(field) {
    const minimum = Number(field?.range?.minimum);
    const maximum = Number(field?.range?.maximum);
    const step = Number(field?.range?.step);
    if (
        field?.type !== "number" ||
        !Number.isFinite(minimum) ||
        !Number.isFinite(maximum) ||
        !Number.isFinite(step) ||
        minimum > maximum ||
        step <= 0
    ) {
        return null;
    }
    return { minimum, maximum, step };
}

export function filterParam(key, operator) {
    const safeKey = String(key).trim();
    const suffix = operator === "gte" ? ":gte" : operator === "lte" ? ":lte" : "";
    return `filter_${safeKey}${suffix}`;
}

export function legacyFilterParam(key, operator) {
    const safeKey = String(key).trim();
    const suffix = operator === "gte" ? "_min" : operator === "lte" ? "_max" : "";
    return `filter_${safeKey}${suffix}`;
}

export function schemaBrands(schema) {
    if (!schema || typeof schema !== "object" || !Array.isArray(schema.brands)) {
        return [];
    }
    return schema.brands.filter(
        (brand) =>
            brand &&
            typeof brand === "object" &&
            typeof brand.slug === "string" &&
            brand.slug.trim() &&
            typeof brand.name === "string" &&
            brand.name.trim(),
    );
}

function numeric(value) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : Number.MAX_SAFE_INTEGER;
}

function isMetadataKey(value) {
    return /^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(value);
}

const schemaRequests = new Map<string, Promise<unknown>>();

export async function loadSchema(url) {
    const key = url.href;
    const existing = schemaRequests.get(key);
    if (existing) {
        return existing;
    }
    const request = fetch(url, {
        credentials: "include",
        headers: { accept: "application/json" },
    })
        .then(async (response) => {
            const body = await response.json().catch(() => null);
            if (!response.ok) {
                throw new Error(
                    response.status === 404 ? "Catégorie indisponible." : "Impossible de charger les filtres.",
                );
            }
            if (!body || typeof body !== "object" || Array.isArray(body)) {
                throw new Error("Réponse de filtres invalide.");
            }
            return body;
        })
        .finally(() => schemaRequests.delete(key));
    schemaRequests.set(key, request);
    return request;
}

export function schemaSourceUrl(host) {
    const prefix = (host.getAttribute("source-prefix") || "/.cms/sources").replace(/\/+$/, "");
    const sourceId = encodeURIComponent(host.getAttribute("source-id") || "commerce");
    const endpoint = encodeURIComponent(host.getAttribute("schema-endpoint") || "offerFilterSchema");
    return `${prefix}/${sourceId}/${endpoint}`;
}

import { filterControls, filterableFields, legacyFilterParam, numericRange } from "./schema-helpers";
import { snapRangeValue } from "../range/range-values";

export function prepareSchemaFilterParams(host, schema) {
    if (typeof location === "undefined" || typeof history === "undefined") {
        return;
    }
    const params = new URLSearchParams(location.search);
    const migrated = migrateLegacyFilterParams(params, schema);
    const canonicalized = canonicalizeNumericFilterParams(params, schema);
    const changed = migrated || canonicalized;
    if (!changed) {
        return;
    }
    const query = params.toString();
    history.replaceState(history.state, "", `${location.pathname}${query ? `?${query}` : ""}${location.hash}`);
    queueMicrotask(() => host.ownerDocument.dispatchEvent(new Event("cms-params:change")));
}

function migrateLegacyFilterParams(params, schema) {
    const candidates = new Map();
    for (const field of filterableFields(schema)) {
        for (const control of filterControls(field)) {
            const legacy = legacyFilterParam(field.key, control.operator);
            const targets = candidates.get(legacy) || new Set();
            targets.add(control.param);
            candidates.set(legacy, targets);
        }
    }
    let changed = false;
    for (const [legacy, targets] of candidates) {
        if (!params.has(legacy) || targets.size !== 1) {
            continue;
        }
        const [current] = targets;
        if (current === legacy) {
            continue;
        }
        if (!params.has(current)) {
            params.set(current, params.get(legacy) || "");
        }
        params.delete(legacy);
        changed = true;
    }
    return changed;
}

function canonicalizeNumericFilterParams(params, schema) {
    let changed = false;
    for (const field of filterableFields(schema)) {
        const range = numericRange(field);
        if (!range) {
            continue;
        }
        const controls = new Map(filterControls(field).map((control) => [control.operator, control.param]));
        const minimumParam = controls.get("gte");
        const maximumParam = controls.get("lte");
        if (!minimumParam || !maximumParam) {
            continue;
        }
        const maximum = readRangeValue(params, maximumParam, range, range.maximum);
        const minimum = Math.min(readRangeValue(params, minimumParam, range, range.minimum), maximum);
        changed = writeRangeValue(params, minimumParam, minimum, range.minimum) || changed;
        changed = writeRangeValue(params, maximumParam, maximum, range.maximum) || changed;
    }
    return changed;
}

function readRangeValue(params, name, range, fallback) {
    const raw = params.get(name);
    const value = raw === null || raw.trim() === "" ? Number.NaN : Number(raw);
    return snapRangeValue(value, range.minimum, range.maximum, range.step, fallback);
}

function writeRangeValue(params, name, value, boundary) {
    if (value === boundary) {
        const existed = params.has(name);
        params.delete(name);
        return existed;
    }
    const canonical = String(value);
    if (params.get(name) === canonical) {
        return false;
    }
    params.set(name, canonical);
    return true;
}

import { numericRangeStyle } from "../range/range-style";

export const schemaFilterStyle = `
    commerce-offer-filter[schema-driven] [data-schema-filters] {
        display: grid;
        gap: 1rem;
    }

    commerce-offer-filter[schema-driven] [data-schema-field] {
        display: grid;
        gap: .35rem;
        color: var(--text-main, inherit);
        font-size: .925rem;
        font-weight: 700;
    }

    commerce-offer-filter[schema-driven] [data-schema-field] input {
        box-sizing: border-box;
        width: 100%;
        min-height: 2.65rem;
        padding: .55rem .7rem;
        border: 1px solid var(--border-default, color-mix(in srgb, currentColor 22%, transparent));
        border-radius: var(--radius-control, .375rem);
        color: var(--text-main, inherit);
        background: var(--bg-surface, Canvas);
        font: inherit;
        font-weight: 400;
    }

    commerce-offer-filter[schema-driven] [data-schema-field] input:focus-visible {
        outline: 2px solid var(--secondary-base, currentColor);
        outline-offset: 2px;
    }
    ${numericRangeStyle}
`;

import { filterControls, filterableFields } from "./schema-helpers";
import { loadSchema, schemaSourceUrl } from "./schema-loader";
import { prepareSchemaFilterParams } from "./schema-params";
import { renderSchema, renderSchemaState } from "./render-schema";

export class SchemaOfferFilters {
    constructor(host) {
        this.host = host;
        this.category = "";
        this.schema = null;
        this.controller = null;
        this.scheduled = false;
        this.inFlight = null;
        this.connected = false;
        this.scheduleTimer = null;
    }

    connect() {
        if (this.connected) {
            this.schedule();
            return;
        }
        this.connected = true;
        if (!this.schema) {
            this.host.setAttribute("data-schema-status", "pending");
        }
        this.host.ownerDocument.addEventListener("cms-params:change", this.schedule);
        this.host.ownerDocument.defaultView?.addEventListener("popstate", this.schedule);
        this.schedule();
    }

    disconnect() {
        if (!this.connected) {
            return;
        }
        this.connected = false;
        this.host.ownerDocument.removeEventListener("cms-params:change", this.schedule);
        this.host.ownerDocument.defaultView?.removeEventListener("popstate", this.schedule);
        this.controller?.abort();
        this.controller = null;
        this.inFlight = null;
        this.scheduled = false;
        if (this.scheduleTimer) {
            clearTimeout(this.scheduleTimer);
            this.scheduleTimer = null;
        }
    }

    invalidate() {
        this.controller?.abort();
        this.inFlight = null;
        this.category = "";
        this.schema = null;
        this.host.setAttribute("data-schema-status", "pending");
        this.schedule();
    }

    render() {
        if (this.schema) {
            renderSchema(this.host, this.schema);
        }
    }

    renderCurrent() {
        if (this.schema && this.category === this.currentCategory()) {
            this.render();
        }
    }

    schedule = () => {
        if (this.scheduled) {
            return;
        }
        this.scheduled = true;
        this.scheduleTimer = setTimeout(() => {
            this.scheduled = false;
            this.scheduleTimer = null;
            if (this.host.isConnected) {
                void this.sync();
            }
        }, 0);
    };

    async sync() {
        const category = this.currentCategory();
        if (!category) {
            if (this.category) {
                this.clearManagedParams();
            }
            this.controller?.abort();
            this.category = "";
            this.schema = null;
            this.host.removeAttribute("data-schema-category");
            renderSchemaState(this.host, "idle");
            return;
        }
        if (category === this.category && this.schema) {
            return;
        }
        if (this.category && category !== this.category) {
            this.clearManagedParams();
        }
        this.category = category;
        if (this.inFlight?.category === category) {
            return this.inFlight.promise;
        }
        this.controller?.abort();
        const controller = new AbortController();
        this.controller = controller;
        renderSchemaState(this.host, "loading");
        const promise = this.load(category, controller);
        this.inFlight = { category, promise };
        try {
            await promise;
        } finally {
            if (this.inFlight?.promise === promise) {
                this.inFlight = null;
            }
        }
    }

    managedParams() {
        const fields = filterableFields(this.schema);
        return [
            ...(this.host.getAttribute("show-brand") === "false" ? [] : ["brand"]),
            ...fields.flatMap((field) => filterControls(field).map((control) => control.param)),
        ];
    }

    async load(category, controller) {
        try {
            const url = new URL(schemaSourceUrl(this.host), this.host.ownerDocument.baseURI);
            url.searchParams.set("category", category);
            const body = await loadSchema(url);
            if (controller.signal.aborted || !this.host.isConnected || category !== this.category) {
                return;
            }
            prepareSchemaFilterParams(this.host, body);
            this.schema = body;
            renderSchema(this.host, body);
        } catch (error) {
            if (controller.signal.aborted) {
                return;
            }
            console.error(error);
            this.schema = null;
            renderSchemaState(this.host, "error", "Impossible de charger les filtres de cette catégorie.");
        }
    }

    clearManagedParams() {
        if (typeof location === "undefined" || typeof history === "undefined") {
            return;
        }
        const params = new URLSearchParams(location.search);
        let changed = false;
        for (const name of this.managedParams()) {
            if (params.has(name)) {
                params.delete(name);
                changed = true;
            }
        }
        if (!changed) {
            return;
        }
        const query = params.toString();
        history.replaceState(history.state, "", `${location.pathname}${query ? `?${query}` : ""}${location.hash}`);
        queueMicrotask(() => this.host.ownerDocument.dispatchEvent(new Event("cms-params:change")));
    }

    currentCategory() {
        if (typeof location === "undefined") {
            return "";
        }
        return (
            new URLSearchParams(location.search).get(this.host.getAttribute("category-param") || "category")?.trim() ||
            ""
        );
    }
}

