import { requiredEnv } from "./env.ts";
import { HttpError } from "./errors.ts";

export function requireCmsRequest(request: Request): void {
    const expected = requiredEnv("CMS_COMMERCE_API_KEY");
    const authorization = request.headers.get("authorization") ?? "";
    const token = authorization.startsWith("Bearer ") ? authorization.slice("Bearer ".length).trim() : "";
    if (!token || !safeEqual(token, expected)) {
        throw new HttpError(401, "invalid CMS API key");
    }
}

export function cmsUserId(request: Request): string {
    const value = (request.headers.get("x-cms-user-id") ?? "").trim();
    if (!value) {
        throw new HttpError(401, "missing CMS user id");
    }
    return value;
}

export function optionalCmsUserId(request: Request): string {
    return (request.headers.get("x-cms-user-id") ?? "").trim() || "cms-admin";
}

export function requireCmsAdmin(request: Request): void {
    const role = (request.headers.get("x-cms-user-role") ?? "").trim();
    if (role !== "admin") {
        throw new HttpError(403, "CMS admin role is required");
    }
}

function safeEqual(left: string, right: string): boolean {
    if (left.length !== right.length) {
        return false;
    }
    let result = 0;
    for (let index = 0; index < left.length; index++) {
        result |= left.charCodeAt(index) ^ right.charCodeAt(index);
    }
    return result === 0;
}

import { HttpError } from "./errors.ts";
import { isRecord } from "./records.ts";

export function requiredEnv(name: string): string {
    const value = Deno.env.get(name);
    if (!value) {
        throw new HttpError(500, `missing ${name}`);
    }
    return value;
}
export function serviceRoleKey(): string {
    const secretKeys = Deno.env.get("SUPABASE_SECRET_KEYS");
    if (secretKeys) {
        if (!secretKeys.trim().startsWith("{")) {
            const first = secretKeys
                .split(",")
                .map((value) => value.trim())
                .find(Boolean);
            if (first) {
                return first;
            }
        }
        try {
            const parsed = JSON.parse(secretKeys);
            if (isRecord(parsed)) {
                if (typeof parsed.default === "string" && parsed.default) {
                    return parsed.default;
                }
                const first = Object.values(parsed).find((value) => typeof value === "string" && value);
                if (typeof first === "string") {
                    return first;
                }
            }
        } catch {
            throw new HttpError(500, "SUPABASE_SECRET_KEYS must be valid JSON");
        }
    }
    return (
        Deno.env.get("SUPABASE_SECRET_KEY") ??
        Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ??
        requiredEnv("SUPABASE_SERVICE_ROLE_KEY")
    );
}

export class HttpError extends Error {
    constructor(
        readonly status: number,
        message: string,
    ) {
        super(message);
    }
}

import { HttpError } from "./errors.ts";

export const corsHeaders = {
    "access-control-allow-origin": "*",
    "access-control-allow-headers": "authorization, content-type, x-cms-user-id",
    "access-control-allow-methods": "GET, POST, DELETE, OPTIONS",
};

export function json(value: unknown, status = 200): Response {
    return new Response(JSON.stringify(value), {
        status,
        headers: { ...corsHeaders, "content-type": "application/json; charset=utf-8" },
    });
}

export function optionsResponse(): Response {
    return new Response("ok", { headers: corsHeaders });
}

export function methodNotAllowed(...methods: string[]): Response {
    return new Response("Method Not Allowed", {
        status: 405,
        headers: { ...corsHeaders, allow: [...methods, "OPTIONS"].join(", ") },
    });
}

export function handleError(error: unknown): Response {
    if (error instanceof HttpError) {
        return json({ error: error.message }, error.status);
    }
    console.error(error);
    return json({ error: "internal error" }, 500);
}

import { HttpError } from "./errors.ts";
import { isRecord, publicMetadata } from "./records.ts";
import { restJson } from "./rest.ts";
import type { JsonRecord } from "./types.ts";

const metadataTypes = new Set(["string", "number", "boolean", "enum"]);

export type PublicOrderMetadataDefinition = {
    key: string;
    label: string;
    type: string;
    unit?: string;
};

export async function publicOrderMetadataDefinitions(): Promise<PublicOrderMetadataDefinition[]> {
    const rows = await restJson<JsonRecord[]>(
        "custom_field_definitions?select=key,label,field_type,unit&entity_type=eq.order&public_readable=eq.true&enabled=eq.true&order=position.asc,key.asc",
    );
    return parsePublicOrderMetadataDefinitions(rows);
}

export function parsePublicOrderMetadataDefinitions(rows: readonly JsonRecord[]): PublicOrderMetadataDefinition[] {
    return rows.flatMap((row) => {
        const key = stringValue(row.key);
        const type = stringValue(row.field_type);
        if (!key || !type || !metadataTypes.has(type)) {
            return [];
        }
        const unit = stringValue(row.unit);
        return [
            {
                key,
                label: stringValue(row.label) || key,
                type,
                ...(unit ? { unit } : {}),
            },
        ];
    });
}

export function withPublicOrderMetadata(
    row: JsonRecord,
    definitions: readonly PublicOrderMetadataDefinition[],
): JsonRecord {
    const metadata = publicMetadata(row.metadata, new Set(definitions.map((definition) => definition.key)));
    const metadataEntries = definitions.flatMap((definition) => {
        if (!Object.hasOwn(metadata, definition.key)) {
            return [];
        }
        const value = displayValue(metadata[definition.key]);
        if (value === undefined) {
            return [];
        }
        return [
            {
                key: definition.key,
                label: definition.label,
                type: definition.type,
                value,
                ...(definition.unit ? { unit: definition.unit } : {}),
            },
        ];
    });
    return { ...row, metadata, metadataEntries };
}

export function withPublicOrderResult(value: unknown, definitions: readonly PublicOrderMetadataDefinition[]): unknown {
    if (!isRecord(value)) {
        throw new HttpError(502, "invalid order response");
    }
    return withPublicOrderMetadata(value, definitions);
}

export function withPublicCheckoutMetadata(
    value: unknown,
    definitions: readonly PublicOrderMetadataDefinition[],
): unknown {
    if (!isRecord(value) || !Array.isArray(value.orders) || value.orders.some((order) => !isRecord(order))) {
        throw new HttpError(502, "invalid checkout response");
    }
    return {
        ...value,
        orders: value.orders.map((order) => withPublicOrderMetadata(order as JsonRecord, definitions)),
    };
}

function displayValue(value: unknown): string | undefined {
    if (typeof value === "string" || typeof value === "boolean") {
        return String(value);
    }
    if (typeof value === "number" && Number.isFinite(value)) {
        return String(value);
    }
    return undefined;
}

function stringValue(value: unknown): string {
    return typeof value === "string" ? value.trim() : "";
}

import { HttpError } from "./errors.ts";
import type { JsonRecord } from "./types.ts";

export function isRecord(value: unknown): value is JsonRecord {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

export async function readJsonObject(request: Request): Promise<JsonRecord> {
    let value: unknown;
    try {
        value = await request.json();
    } catch {
        throw new HttpError(400, "invalid JSON body");
    }
    if (!isRecord(value)) {
        throw new HttpError(400, "body must be an object");
    }
    return value;
}

export function text(value: unknown): string | undefined {
    return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

export function requiredText(value: unknown, name: string): string {
    const result = text(value);
    if (!result) {
        throw new HttpError(400, `${name} is required`);
    }
    return result;
}

export function integer(value: unknown, name: string, required = false): number | undefined {
    if (value === undefined || value === null || value === "") {
        if (required) {
            throw new HttpError(400, `${name} is required`);
        }
        return undefined;
    }
    const result =
        typeof value === "number"
            ? value
            : typeof value === "string" && /^-?\d+$/.test(value.trim())
              ? Number(value.trim())
              : Number.NaN;
    if (!Number.isSafeInteger(result)) {
        throw new HttpError(400, `${name} must be an integer`);
    }
    return result;
}

export function booleanValue(value: unknown, name: string): boolean | undefined {
    if (value === undefined || value === null || value === "") {
        return undefined;
    }
    if (value === true || value === "true") {
        return true;
    }
    if (value === false || value === "false") {
        return false;
    }
    throw new HttpError(400, `${name} must be a boolean`);
}

export function camelize(value: unknown): unknown {
    if (Array.isArray(value)) {
        return value.map(camelize);
    }
    if (!isRecord(value)) {
        return value;
    }
    return Object.fromEntries(
        Object.entries(value).map(([key, entry]) => [
            camelCase(key),
            opaqueJsonColumns.has(key) ? entry : camelize(entry),
        ]),
    );
}

export function publicMetadata(value: unknown, allowedKeys: Set<string>): JsonRecord {
    if (!isRecord(value)) {
        return {};
    }
    return Object.fromEntries(Object.entries(value).filter(([key]) => allowedKeys.has(key)));
}

function camelCase(value: string): string {
    return value.replace(/_([a-z])/g, (_, letter: string) => letter.toUpperCase());
}

const opaqueJsonColumns = new Set([
    "metadata",
    "data",
    "shipping_address",
    "billing_address",
    "product_snapshot",
    "variant_snapshot",
    "offer_snapshot",
    "seller_snapshot",
]);

import { serviceRoleKey, requiredEnv } from "./env.ts";
import { HttpError } from "./errors.ts";
import { isRecord } from "./records.ts";
import type { JsonRecord } from "./types.ts";

const schema = "commerce";

export async function rest(path: string, init: RequestInit = {}): Promise<Response> {
    const key = serviceRoleKey();
    const base = requiredEnv("SUPABASE_URL").replace(/\/$/, "");
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    // Supabase's current sb_secret_* keys are not JWTs. Sending one as a
    // Bearer token makes PostgREST reject it as an invalid JWT. Legacy
    // service_role JWTs still need both headers.
    if (key.startsWith("sb_")) {
        headers.delete("authorization");
    } else {
        headers.set("authorization", `Bearer ${key}`);
    }
    headers.set("accept-profile", schema);
    if (init.method && init.method !== "GET" && init.method !== "HEAD") {
        headers.set("content-profile", schema);
        headers.set("content-type", "application/json");
    }
    const response = await fetch(`${base}/rest/v1/${path}`, { ...init, headers });
    if (!response.ok) {
        throw await restError(response);
    }
    return response;
}

export async function restJson<T>(path: string, init: RequestInit = {}): Promise<T> {
    const response = await rest(path, init);
    return (await response.json()) as T;
}

export async function rpc(name: string, body: JsonRecord): Promise<unknown> {
    return await restJson(`rpc/${name}`, {
        method: "POST",
        body: JSON.stringify(body),
    });
}

export async function one(
    table: string,
    filters: Record<string, string | number>,
    select = "*",
): Promise<JsonRecord | null> {
    const params = new URLSearchParams({ select, limit: "1" });
    for (const [key, value] of Object.entries(filters)) {
        params.set(key, `eq.${String(value)}`);
    }
    const rows = await restJson<JsonRecord[]>(`${table}?${params.toString()}`);
    return rows[0] ?? null;
}

export async function listRows(path: string): Promise<{ rows: JsonRecord[]; total: number }> {
    const response = await rest(path, { headers: { prefer: "count=exact" } });
    const rows = (await response.json()) as JsonRecord[];
    const range = response.headers.get("content-range") ?? "";
    const totalText = range.includes("/") ? range.slice(range.lastIndexOf("/") + 1) : "";
    const total = Number(totalText);
    return { rows, total: Number.isFinite(total) ? total : rows.length };
}

async function restError(response: Response): Promise<HttpError> {
    const data = await response.json().catch(() => null);
    const message =
        isRecord(data) && typeof data.message === "string"
            ? data.message
            : `Supabase request failed (${response.status})`;
    if (message.startsWith("validation:")) {
        return new HttpError(422, message.slice("validation:".length).trim());
    }
    if (message.startsWith("conflict:")) {
        return new HttpError(409, message.slice("conflict:".length).trim());
    }
    if (message.startsWith("forbidden:")) {
        return new HttpError(403, message.slice("forbidden:".length).trim());
    }
    if (message.startsWith("not_found:")) {
        return new HttpError(404, message.slice("not_found:".length).trim());
    }
    if (response.status === 409) {
        return new HttpError(409, message);
    }
    if (response.status === 400 || response.status === 422) {
        return new HttpError(422, message);
    }
    return new HttpError(502, message);
}

import { requireCmsRequest } from "./core/auth.ts";
import { handleError, json, optionsResponse } from "./core/http.ts";
import { handleAdminConfigurationRoute } from "./routing/admin-configuration.ts";
import { handleAdminMarketplaceRoute } from "./routing/admin-marketplace.ts";
import { handleCatalogRoute } from "./routing/catalog.ts";
import { handleMarketplaceRoute } from "./routing/marketplace.ts";
import { handleInternalSettlementRoute } from "./routing/internal-settlement.ts";
import { handleNotificationRoute } from "./routing/notifications.ts";

const routeHandlers = [
    handleCatalogRoute,
    handleMarketplaceRoute,
    handleInternalSettlementRoute,
    handleAdminMarketplaceRoute,
    handleAdminConfigurationRoute,
    handleNotificationRoute,
];

export async function handleCommerceRequest(request: Request): Promise<Response> {
    try {
        if (request.method === "OPTIONS") {
            return optionsResponse();
        }
        requireCmsRequest(request);
        const route = routePath(request);

        for (const handler of routeHandlers) {
            const response = await handler(route, request);
            if (response) {
                return response;
            }
        }
        return json({ error: "not found" }, 404);
    } catch (error) {
        return handleError(error);
    }
}

function routePath(request: Request): string {
    const pathname = new URL(request.url).pathname.replace(/\/+$/, "");
    const marker = "/cms-commerce";
    const index = pathname.indexOf(marker);
    if (index === -1) {
        return pathname || "/";
    }
    return pathname.slice(index + marker.length) || "/";
}

import { cmsUserId } from "../../core/auth.ts";
import { HttpError } from "../../core/errors.ts";
import { json } from "../../core/http.ts";
import { camelize, integer, isRecord, readJsonObject, requiredText } from "../../core/records.ts";
import { rpc } from "../../core/rest.ts";
import { publicOrderMetadataDefinitions, withPublicCheckoutMetadata } from "../../core/order-metadata.ts";

export async function getCart(request: Request): Promise<Response> {
    const result = await rpc("get_cart", {
        p_buyer_cms_user_id: cmsUserId(request),
    });
    return json(camelize(result));
}

export async function upsertCartItem(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const result = await rpc("upsert_cart_item", {
        p_buyer_cms_user_id: cmsUserId(request),
        p_offer_id: integer(body.offerId, "offerId", true),
        p_quantity: integer(body.quantity, "quantity", true),
        p_expected_version: integer(body.expectedVersion, "expectedVersion"),
    });
    return json(camelize(result));
}

export async function removeCartItem(request: Request): Promise<Response> {
    const params = new URL(request.url).searchParams;
    const result = await rpc("remove_cart_item", {
        p_buyer_cms_user_id: cmsUserId(request),
        p_offer_id: integer(params.get("offerId"), "offerId", true),
        p_expected_version: integer(params.get("expectedVersion"), "expectedVersion", true),
    });
    return json(camelize(result));
}

export async function clearCart(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const result = await rpc("clear_cart", {
        p_buyer_cms_user_id: cmsUserId(request),
        p_expected_version: integer(body.expectedVersion, "expectedVersion", true),
    });
    return json(camelize(result));
}

export async function checkoutCart(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    assertOptionalObjects(body);
    const buyerCmsUserId = cmsUserId(request);
    const expectedVersion = integer(body.expectedVersion, "expectedVersion", true);
    const idempotencyKey = requiredText(body.idempotencyKey, "idempotencyKey");
    const definitions = await publicOrderMetadataDefinitions();
    const checkout = await rpc("checkout_cart", {
        p_buyer_cms_user_id: buyerCmsUserId,
        p_expected_version: expectedVersion,
        p_idempotency_key: idempotencyKey,
        p_shipping_address: isRecord(body.shippingAddress) ? body.shippingAddress : {},
        p_billing_address: isRecord(body.billingAddress) ? body.billingAddress : {},
        p_metadata: isRecord(body.metadata) ? body.metadata : {},
    });
    const result = withPublicCheckoutMetadata(camelize(checkout), definitions);
    const replay = isRecord(result) && result.idempotentReplay === true;
    return json(result, replay ? 200 : 201);
}

function assertOptionalObjects(body: Record<string, unknown>): void {
    for (const key of ["shippingAddress", "billingAddress", "metadata"] as const) {
        if (body[key] !== undefined && !isRecord(body[key])) {
            throw new HttpError(400, `${key} must be an object`);
        }
    }
}

export const productMediaBucket = "commerce-media";
export const maxProductImageBytes = 10 * 1024 * 1024;
export const maxProductImagePixels = 40_000_000;
export const maxMultipartOverheadBytes = 256 * 1024;

import { HttpError } from "../../../core/errors.ts";
import { maxMultipartOverheadBytes } from "./constants.ts";
import { parseSingleMultipartFile } from "./multipartParser.ts";
import type { MultipartFile } from "./multipartParser.ts";

export type { MultipartFile } from "./multipartParser.ts";

export async function readSingleMultipartFile(request: Request, maxFileBytes: number): Promise<MultipartFile> {
    const boundary = multipartBoundary(request.headers.get("content-type"));
    const maxBodyBytes = maxFileBytes + maxMultipartOverheadBytes;
    rejectKnownOversize(request, maxBodyBytes);
    const bytes = await readBoundedBody(request, maxBodyBytes);
    return parseSingleMultipartFile(bytes, boundary, maxFileBytes);
}

function multipartBoundary(contentType: string | null): string {
    if (!contentType || !/^multipart\/form-data(?:;|$)/i.test(contentType.trim())) {
        throw new HttpError(400, "image upload must use multipart/form-data");
    }
    const match = /;\s*boundary=(?:"([^"]+)"|([^;]+))/i.exec(contentType);
    const boundary = (match?.[1] ?? match?.[2] ?? "").trim();
    if (!boundary || boundary.length > 70 || /[\r\n\x00-\x1f\x7f]/.test(boundary)) {
        throw new HttpError(400, "invalid multipart boundary");
    }
    return boundary;
}

function rejectKnownOversize(request: Request, maxBodyBytes: number): void {
    const raw = request.headers.get("content-length")?.trim();
    if (!raw || !/^[0-9]+$/.test(raw)) {
        return;
    }
    const length = Number(raw);
    if (Number.isSafeInteger(length) && length > maxBodyBytes) {
        void request.body?.cancel("multipart body exceeds the configured limit").catch(() => undefined);
        throw new HttpError(413, "file is too large");
    }
}

async function readBoundedBody(request: Request, maxBodyBytes: number): Promise<Uint8Array> {
    if (!request.body) {
        throw new HttpError(400, "invalid multipart body");
    }
    const reader = request.body.getReader();
    const chunks: Uint8Array[] = [];
    let total = 0;
    try {
        for (;;) {
            const result = await reader.read();
            if (result.done) {
                break;
            }
            total += result.value.byteLength;
            if (total > maxBodyBytes) {
                await reader.cancel("multipart body exceeds the configured limit").catch(() => undefined);
                throw new HttpError(413, "file is too large");
            }
            chunks.push(result.value);
        }
    } catch (error) {
        if (error instanceof HttpError) {
            throw error;
        }
        await reader.cancel("invalid multipart body").catch(() => undefined);
        throw new HttpError(400, "invalid multipart body");
    } finally {
        reader.releaseLock();
    }
    return concatenate(chunks, total);
}

function concatenate(chunks: Uint8Array[], total: number): Uint8Array {
    const result = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) {
        result.set(chunk, offset);
        offset += chunk.byteLength;
    }
    return result;
}

import { HttpError } from "../../../core/errors.ts";

export type MultipartFile = {
    bytes: Uint8Array;
    filename: string;
};

const decoder = new TextDecoder();
const encoder = new TextEncoder();
const maxHeaderBytes = 16 * 1024;

export function parseSingleMultipartFile(bytes: Uint8Array, boundary: string, maxFileBytes: number): MultipartFile {
    const marker = encoder.encode(`--${boundary}`);
    const delimiter = encoder.encode(`\r\n--${boundary}`);
    if (!matchesAt(bytes, marker, 0)) {
        throw new HttpError(400, "invalid multipart body");
    }
    let cursor = marker.length;
    let file: MultipartFile | null = null;
    for (;;) {
        if (matchesAscii(bytes, "--", cursor)) {
            cursor += 2;
            if (cursor === bytes.length) {
                break;
            }
            if (!matchesAscii(bytes, "\r\n", cursor) || cursor + 2 !== bytes.length) {
                throw new HttpError(400, "invalid multipart body");
            }
            break;
        }
        if (!matchesAscii(bytes, "\r\n", cursor)) {
            throw new HttpError(400, "invalid multipart body");
        }
        cursor += 2;
        const headerEnd = indexOf(bytes, encoder.encode("\r\n\r\n"), cursor);
        if (headerEnd < 0 || headerEnd - cursor > maxHeaderBytes) {
            throw new HttpError(400, "invalid multipart headers");
        }
        const headers = parseHeaders(bytes.subarray(cursor, headerEnd));
        const contentStart = headerEnd + 4;
        const nextBoundary = indexOf(bytes, delimiter, contentStart);
        if (nextBoundary < 0) {
            throw new HttpError(400, "invalid multipart body");
        }
        const disposition = contentDisposition(headers.get("content-disposition"));
        if (disposition.filename !== null) {
            if (disposition.name !== "file" || file) {
                throw new HttpError(400, "exactly one file is required");
            }
            const contents = bytes.slice(contentStart, nextBoundary);
            if (contents.byteLength === 0) {
                throw new HttpError(400, "file is empty");
            }
            if (contents.byteLength > maxFileBytes) {
                throw new HttpError(413, "file is too large");
            }
            file = {
                bytes: contents,
                filename: safeFilename(disposition.filename),
            };
        }
        cursor = nextBoundary + 2 + marker.length;
    }
    if (!file) {
        throw new HttpError(400, "file is required");
    }
    return file;
}

function parseHeaders(bytes: Uint8Array): Map<string, string> {
    const value = decoder.decode(bytes);
    const headers = new Map<string, string>();
    for (const line of value.split("\r\n")) {
        const separator = line.indexOf(":");
        if (separator <= 0 || /^[ \t]/.test(line)) {
            throw new HttpError(400, "invalid multipart headers");
        }
        const name = line.slice(0, separator).trim().toLowerCase();
        const content = line.slice(separator + 1).trim();
        if (!/^[a-z0-9!#$%&'*+.^_`|~-]+$/.test(name) || headers.has(name)) {
            throw new HttpError(400, "invalid multipart headers");
        }
        headers.set(name, content);
    }
    return headers;
}

function contentDisposition(value: string | undefined): { filename: string | null; name: string | null } {
    if (!value || !/^form-data(?:;|$)/i.test(value.trim())) {
        throw new HttpError(400, "invalid multipart disposition");
    }
    return {
        filename: dispositionParameter(value, "filename"),
        name: dispositionParameter(value, "name"),
    };
}

function dispositionParameter(value: string, name: string): string | null {
    const expression = new RegExp(`(?:^|;)\\s*${name}=(?:"((?:[^"\\\\]|\\\\.)*)"|([^;]*))`, "i");
    const match = expression.exec(value);
    if (!match) {
        return null;
    }
    const raw = match[1] === undefined ? (match[2] ?? "").trim() : match[1].replace(/\\(.)/g, "$1");
    if (/[\r\n\x00]/.test(raw)) {
        throw new HttpError(400, "invalid multipart disposition");
    }
    return raw;
}

function safeFilename(value: string): string {
    const filename = value.split(/[\\/]/).at(-1)?.trim() ?? "";
    return filename || "image";
}

function indexOf(haystack: Uint8Array, needle: Uint8Array, start: number): number {
    outer: for (let index = start; index <= haystack.length - needle.length; index++) {
        for (let offset = 0; offset < needle.length; offset++) {
            if (haystack[index + offset] !== needle[offset]) {
                continue outer;
            }
        }
        return index;
    }
    return -1;
}

function matchesAt(bytes: Uint8Array, value: Uint8Array, offset: number): boolean {
    return value.every((byte, index) => bytes[offset + index] === byte);
}

function matchesAscii(bytes: Uint8Array, value: string, offset: number): boolean {
    return matchesAt(bytes, encoder.encode(value), offset);
}

import { ascii, malformed, readU16BE, readU32BE, readU64BE, requireBytes, unsupportedAnimation } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

type Box = { end: number; payload: number; type: string };
type ParseState = { boxes: number };

const maxBoxes = 4096;

export function isAvif(bytes: Uint8Array): boolean {
    return bytes.length >= 16 && ascii(bytes, 4, 4) === "ftyp" && avifBrand(bytes);
}

export function avifDimensions(bytes: Uint8Array): ImageDimensions {
    const state = { boxes: 0 };
    const top = boxes(bytes, 0, bytes.length, state);
    const ftyp = top.find((box) => box.type === "ftyp");
    const meta = top.find((box) => box.type === "meta");
    const mediaData = top.find((box) => box.type === "mdat");
    if (!ftyp || !meta || !mediaData || mediaData.end === mediaData.payload || !avifBrand(bytes, ftyp)) {
        malformed();
    }
    if (hasBrand(bytes, ftyp, "avis")) {
        unsupportedAnimation();
    }
    requireBytes(bytes, meta.payload, 4);
    const children = boxes(bytes, meta.payload + 4, meta.end, state);
    if (!children.some((box) => box.type === "iloc") || !children.some((box) => box.type === "iinf")) {
        malformed();
    }
    const primaryId = primaryItemId(
        bytes,
        children.find((box) => box.type === "pitm"),
    );
    const iprp = children.find((box) => box.type === "iprp");
    if (!iprp) {
        malformed();
    }
    const propertyBoxes = boxes(bytes, iprp.payload, iprp.end, state);
    const ipco = propertyBoxes.find((box) => box.type === "ipco");
    if (!ipco) {
        malformed();
    }
    const properties = boxes(bytes, ipco.payload, ipco.end, state);
    const dimensionsByProperty = new Map<number, ImageDimensions>();
    const rotationsByProperty = new Map<number, number>();
    properties.forEach((property, index) => {
        if (property.type === "ispe") {
            dimensionsByProperty.set(index + 1, ispeDimensions(bytes, property));
        }
        if (property.type === "irot") {
            requireBytes(bytes, property.payload, 1);
            rotationsByProperty.set(index + 1, bytes[property.payload]! & 0x03);
        }
    });
    if (!dimensionsByProperty.size) {
        malformed();
    }
    if (primaryId !== null) {
        for (const ipma of propertyBoxes.filter((box) => box.type === "ipma")) {
            const propertyIds = associatedPropertyIds(bytes, ipma, primaryId);
            for (const propertyId of propertyIds) {
                const dimensions = dimensionsByProperty.get(propertyId);
                if (dimensions) {
                    const swapsAxes = propertyIds.some((id) => (rotationsByProperty.get(id) ?? 0) % 2 === 1);
                    return swapsAxes ? { width: dimensions.height, height: dimensions.width } : dimensions;
                }
            }
        }
    }
    return [...dimensionsByProperty.values()].sort(
        (left, right) => right.width * right.height - left.width * left.height,
    )[0]!;
}

function avifBrand(bytes: Uint8Array, knownBox?: Box): boolean {
    const box = knownBox ?? boxes(bytes, 0, bytes.length, { boxes: 0 })[0];
    if (!box || box.type !== "ftyp" || box.end - box.payload < 8) {
        return false;
    }
    return hasBrand(bytes, box, "avif") || hasBrand(bytes, box, "avis");
}

function hasBrand(bytes: Uint8Array, box: Box, expected: string): boolean {
    for (let offset = box.payload; offset + 4 <= box.end; offset += 4) {
        if (ascii(bytes, offset, 4) === expected) {
            return true;
        }
    }
    return false;
}

function boxes(bytes: Uint8Array, start: number, end: number, state: ParseState): Box[] {
    const result: Box[] = [];
    let offset = start;
    while (offset < end) {
        requireBytes(bytes, offset, 8);
        if (++state.boxes > maxBoxes) {
            malformed();
        }
        const size32 = readU32BE(bytes, offset);
        const type = ascii(bytes, offset + 4, 4);
        const header = size32 === 1 ? 16 : 8;
        const size = size32 === 0 ? end - offset : size32 === 1 ? readU64BE(bytes, offset + 8) : size32;
        if (size < header || offset + size > end) {
            malformed();
        }
        result.push({ type, payload: offset + header, end: offset + size });
        offset += size;
        if (size32 === 0) {
            break;
        }
    }
    if (offset !== end) {
        malformed();
    }
    return result;
}

function primaryItemId(bytes: Uint8Array, box: Box | undefined): number | null {
    if (!box) {
        return null;
    }
    requireBytes(bytes, box.payload, 6);
    const version = bytes[box.payload]!;
    return version === 0 ? readU16BE(bytes, box.payload + 4) : readU32BE(bytes, box.payload + 4);
}

function ispeDimensions(bytes: Uint8Array, box: Box): ImageDimensions {
    requireBytes(bytes, box.payload, 12);
    return {
        width: readU32BE(bytes, box.payload + 4),
        height: readU32BE(bytes, box.payload + 8),
    };
}

function associatedPropertyIds(bytes: Uint8Array, box: Box, targetId: number): number[] {
    requireBytes(bytes, box.payload, 8);
    const version = bytes[box.payload]!;
    const flags = (bytes[box.payload + 1]! << 16) | (bytes[box.payload + 2]! << 8) | bytes[box.payload + 3]!;
    let offset = box.payload + 4;
    const entries = readU32BE(bytes, offset);
    offset += 4;
    if (entries > maxBoxes) {
        malformed();
    }
    for (let entry = 0; entry < entries; entry++) {
        const itemId = version < 1 ? readU16BE(bytes, offset) : readU32BE(bytes, offset);
        offset += version < 1 ? 2 : 4;
        requireBytes(bytes, offset, 1);
        const count = bytes[offset++]!;
        const propertyIds: number[] = [];
        for (let association = 0; association < count; association++) {
            const wide = (flags & 1) !== 0;
            const encoded = wide ? readU16BE(bytes, offset) : bytes[offset]!;
            offset += wide ? 2 : 1;
            propertyIds.push(encoded & (wide ? 0x7fff : 0x7f));
        }
        if (itemId === targetId) {
            return propertyIds.filter((id) => id > 0);
        }
    }
    if (offset > box.end) {
        malformed();
    }
    return [];
}

import { HttpError } from "../../../../core/errors.ts";

export function ascii(bytes: Uint8Array, offset: number, length: number): string {
    if (offset < 0 || length < 0 || offset + length > bytes.length) {
        malformed();
    }
    return String.fromCharCode(...bytes.subarray(offset, offset + length));
}

export function matches(bytes: Uint8Array, offset: number, expected: readonly number[]): boolean {
    return expected.every((byte, index) => bytes[offset + index] === byte);
}

export function readU16BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 2);
    return (bytes[offset]! << 8) | bytes[offset + 1]!;
}

export function readU16LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 2);
    return bytes[offset]! | (bytes[offset + 1]! << 8);
}

export function readU24LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 3);
    return bytes[offset]! | (bytes[offset + 1]! << 8) | (bytes[offset + 2]! << 16);
}

export function readU32BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 4);
    return new DataView(bytes.buffer, bytes.byteOffset + offset, 4).getUint32(0, false);
}

export function readU32LE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 4);
    return new DataView(bytes.buffer, bytes.byteOffset + offset, 4).getUint32(0, true);
}

export function readU64BE(bytes: Uint8Array, offset: number): number {
    requireBytes(bytes, offset, 8);
    const value = new DataView(bytes.buffer, bytes.byteOffset + offset, 8).getBigUint64(0, false);
    if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
        malformed();
    }
    return Number(value);
}

export function requireBytes(bytes: Uint8Array, offset: number, length: number): void {
    if (offset < 0 || length < 0 || offset + length > bytes.length) {
        malformed();
    }
}

export function malformed(): never {
    throw new HttpError(400, "file is not a valid supported image");
}

export function unsupportedAnimation(): never {
    throw new HttpError(400, "animated images are not supported");
}

export function exifOrientation(bytes: Uint8Array): number | null {
    const tiff = bytes.length >= 6 && ascii(bytes, 0, 6) === "Exif\u0000\u0000" ? bytes.subarray(6) : bytes;
    if (tiff.length < 8) {
        return null;
    }
    const endian = ascii(tiff, 0, 2);
    if (endian !== "II" && endian !== "MM") {
        return null;
    }
    const read16 = endian === "II" ? readU16LE : readU16BE;
    const read32 = endian === "II" ? readU32LE : readU32BE;
    try {
        if (read16(tiff, 2) !== 42) {
            return null;
        }
        const ifdOffset = read32(tiff, 4);
        const count = read16(tiff, ifdOffset);
        if (count > 512) {
            return null;
        }
        for (let index = 0; index < count; index++) {
            const entry = ifdOffset + 2 + index * 12;
            requireBytes(tiff, entry, 12);
            if (read16(tiff, entry) !== 0x0112 || read16(tiff, entry + 2) !== 3 || read32(tiff, entry + 4) !== 1) {
                continue;
            }
            const orientation = read16(tiff, entry + 8);
            return orientation >= 1 && orientation <= 8 ? orientation : null;
        }
    } catch {
        return null;
    }
    return null;
}

import { ascii, malformed, readU16LE, requireBytes, unsupportedAnimation } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

export function isGif(bytes: Uint8Array): boolean {
    const header = bytes.length >= 6 ? ascii(bytes, 0, 6) : "";
    return header === "GIF87a" || header === "GIF89a";
}

export function gifDimensions(bytes: Uint8Array): ImageDimensions {
    requireBytes(bytes, 0, 13);
    if (!isGif(bytes)) {
        malformed();
    }
    const dimensions = { width: readU16LE(bytes, 6), height: readU16LE(bytes, 8) };
    let offset = 13 + colorTableLength(bytes[10]!);
    requireBytes(bytes, 0, offset);
    let frames = 0;
    while (offset < bytes.length) {
        const marker = bytes[offset++]!;
        if (marker === 0x3b) {
            if (frames !== 1 || offset !== bytes.length) {
                malformed();
            }
            return dimensions;
        }
        if (marker === 0x21) {
            requireBytes(bytes, offset, 1);
            offset = skipSubBlocks(bytes, offset + 1, false);
            continue;
        }
        if (marker !== 0x2c) {
            malformed();
        }
        frames++;
        if (frames > 1) {
            unsupportedAnimation();
        }
        requireBytes(bytes, offset, 9);
        const left = readU16LE(bytes, offset);
        const top = readU16LE(bytes, offset + 2);
        const width = readU16LE(bytes, offset + 4);
        const height = readU16LE(bytes, offset + 6);
        if (!width || !height || left + width > dimensions.width || top + height > dimensions.height) {
            malformed();
        }
        offset += 9;
        offset += colorTableLength(bytes[offset - 1]!);
        requireBytes(bytes, offset, 1);
        const minimumCodeSize = bytes[offset++]!;
        if (minimumCodeSize < 2 || minimumCodeSize > 8) {
            malformed();
        }
        offset = skipSubBlocks(bytes, offset, true);
    }
    malformed();
}

function colorTableLength(packed: number): number {
    return packed & 0x80 ? 3 * 2 ** ((packed & 0x07) + 1) : 0;
}

function skipSubBlocks(bytes: Uint8Array, start: number, requireData: boolean): number {
    let offset = start;
    let dataBytes = 0;
    while (offset < bytes.length) {
        const length = bytes[offset++]!;
        if (length === 0) {
            if (requireData && dataBytes === 0) {
                malformed();
            }
            return offset;
        }
        requireBytes(bytes, offset, length);
        dataBytes += length;
        offset += length;
    }
    malformed();
}

import { HttpError } from "../../../../core/errors.ts";
import { maxProductImagePixels } from "../constants.ts";
import { avifDimensions, isAvif } from "./avif.ts";
import { gifDimensions, isGif } from "./gif.ts";
import { isJpeg, jpegDimensions } from "./jpeg.ts";
import { isPng, pngDimensions } from "./png.ts";
import type { ImageDimensions, ProbedImage } from "./types.ts";
import { isWebp, webpDimensions } from "./webp.ts";

export type { ImageDimensions, ProbedImage } from "./types.ts";

export function probeCommerceImage(bytes: Uint8Array): ProbedImage {
    const image = detectedImage(bytes);
    validateDimensions(image);
    return image;
}

function detectedImage(bytes: Uint8Array): ProbedImage {
    if (isJpeg(bytes)) {
        return { ...jpegDimensions(bytes), mimeType: "image/jpeg", extension: ".jpg" };
    }
    if (isPng(bytes)) {
        return { ...pngDimensions(bytes), mimeType: "image/png", extension: ".png" };
    }
    if (isWebp(bytes)) {
        return { ...webpDimensions(bytes), mimeType: "image/webp", extension: ".webp" };
    }
    if (isGif(bytes)) {
        return { ...gifDimensions(bytes), mimeType: "image/gif", extension: ".gif" };
    }
    if (isAvif(bytes)) {
        return { ...avifDimensions(bytes), mimeType: "image/avif", extension: ".avif" };
    }
    throw new HttpError(400, "file must be a JPEG, PNG, WebP, GIF, or AVIF image");
}

function validateDimensions(dimensions: ImageDimensions): void {
    const { width, height } = dimensions;
    if (
        !Number.isSafeInteger(width) ||
        !Number.isSafeInteger(height) ||
        width <= 0 ||
        height <= 0 ||
        width * height > maxProductImagePixels
    ) {
        throw new HttpError(400, "image dimensions are invalid or too large");
    }
}

import { exifOrientation, malformed, matches, readU16BE, requireBytes } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

const startOfFrameMarkers = new Set([0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf]);

export function isJpeg(bytes: Uint8Array): boolean {
    return matches(bytes, 0, [0xff, 0xd8, 0xff]);
}

export function jpegDimensions(bytes: Uint8Array): ImageDimensions {
    if (!isJpeg(bytes)) {
        malformed();
    }
    let offset = 2;
    let orientation = 1;
    let dimensions: ImageDimensions | null = null;
    let sawQuantization = false;
    let sawCodingTable = false;
    let sawScan = false;
    let sawEnd = false;
    let entropyBytes = 0;
    while (offset < bytes.length) {
        if (bytes[offset] !== 0xff) {
            malformed();
        }
        while (bytes[offset] === 0xff) {
            offset++;
        }
        requireBytes(bytes, offset, 1);
        const marker = bytes[offset++]!;
        if (marker === 0xd9) {
            sawEnd = true;
            break;
        }
        if (marker === 0x00 || marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
            if (marker === 0x00 || marker === 0xd8) {
                malformed();
            }
            continue;
        }
        const segmentLength = readU16BE(bytes, offset);
        if (segmentLength < 2) {
            malformed();
        }
        const payload = offset + 2;
        const payloadLength = segmentLength - 2;
        requireBytes(bytes, payload, payloadLength);
        if (marker === 0xe1) {
            orientation = exifOrientation(bytes.subarray(payload, payload + payloadLength)) ?? orientation;
        }
        if (marker === 0xdb) {
            sawQuantization = true;
        }
        if (marker === 0xc4 || marker === 0xcc) {
            sawCodingTable = true;
        }
        if (startOfFrameMarkers.has(marker)) {
            requireBytes(bytes, payload, 6);
            const components = bytes[payload + 5]!;
            if (!components || segmentLength !== 8 + components * 3) {
                malformed();
            }
            dimensions = {
                width: readU16BE(bytes, payload + 3),
                height: readU16BE(bytes, payload + 1),
            };
        }
        if (marker === 0xda) {
            if (!dimensions || payloadLength < 6) {
                malformed();
            }
            sawScan = true;
            const scan = scanEntropy(bytes, payload + payloadLength);
            entropyBytes += scan.bytes;
            offset = scan.nextMarker;
            continue;
        }
        offset += segmentLength;
    }
    if (
        !dimensions ||
        !sawQuantization ||
        !sawCodingTable ||
        !sawScan ||
        !sawEnd ||
        entropyBytes === 0 ||
        offset !== bytes.length
    ) {
        malformed();
    }
    return orientation >= 5 && orientation <= 8 ? { width: dimensions.height, height: dimensions.width } : dimensions;
}

function scanEntropy(bytes: Uint8Array, start: number): { bytes: number; nextMarker: number } {
    let offset = start;
    let dataBytes = 0;
    while (offset < bytes.length) {
        if (bytes[offset] !== 0xff) {
            dataBytes++;
            offset++;
            continue;
        }
        const markerStart = offset;
        while (bytes[offset] === 0xff) {
            offset++;
        }
        requireBytes(bytes, offset, 1);
        const marker = bytes[offset]!;
        if (marker === 0x00) {
            dataBytes++;
            offset++;
            continue;
        }
        if (marker >= 0xd0 && marker <= 0xd7) {
            offset++;
            continue;
        }
        return { bytes: dataBytes, nextMarker: markerStart };
    }
    malformed();
}

import { ascii, exifOrientation, malformed, matches, readU32BE, requireBytes, unsupportedAnimation } from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

const signature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] as const;
const crc32Table = buildCrc32Table();

function buildCrc32Table(): Readonly<Uint32Array> {
    const table = new Uint32Array(256);
    for (let value = 0; value < table.length; value++) {
        let crc = value;
        for (let bit = 0; bit < 8; bit++) {
            crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
        }
        table[value] = crc >>> 0;
    }
    return table;
}

export function isPng(bytes: Uint8Array): boolean {
    return matches(bytes, 0, signature);
}

export function pngDimensions(bytes: Uint8Array): ImageDimensions {
    if (!isPng(bytes)) {
        malformed();
    }
    let offset = signature.length;
    let dimensions: ImageDimensions | null = null;
    let sawImageData = false;
    let imageDataEnded = false;
    let orientation = 1;
    while (offset < bytes.length) {
        requireBytes(bytes, offset, 12);
        const length = readU32BE(bytes, offset);
        const type = ascii(bytes, offset + 4, 4);
        const payload = offset + 8;
        const end = payload + length;
        requireBytes(bytes, payload, length + 4);
        if (crc32(bytes.subarray(offset + 4, end)) !== readU32BE(bytes, end)) {
            malformed();
        }
        if (type === "IHDR") {
            if (dimensions || offset !== signature.length || length !== 13) {
                malformed();
            }
            dimensions = readHeader(bytes, payload);
        } else if (type === "acTL") {
            unsupportedAnimation();
        } else if (type === "eXIf") {
            orientation = exifOrientation(bytes.subarray(payload, end)) ?? orientation;
        } else if (type === "IDAT") {
            if (!dimensions || imageDataEnded || length === 0) {
                malformed();
            }
            sawImageData = true;
        } else if (sawImageData && type !== "IEND") {
            imageDataEnded = true;
        }
        offset = end + 4;
        if (type === "IEND") {
            if (length !== 0 || !dimensions || !sawImageData || offset !== bytes.length) {
                malformed();
            }
            return orientation >= 5 && orientation <= 8
                ? { width: dimensions.height, height: dimensions.width }
                : dimensions;
        }
    }
    malformed();
}

function readHeader(bytes: Uint8Array, offset: number): ImageDimensions {
    const bitDepth = bytes[offset + 8]!;
    const colorType = bytes[offset + 9]!;
    const allowedDepths: Record<number, readonly number[]> = {
        0: [1, 2, 4, 8, 16],
        2: [8, 16],
        3: [1, 2, 4, 8],
        4: [8, 16],
        6: [8, 16],
    };
    if (
        !allowedDepths[colorType]?.includes(bitDepth) ||
        bytes[offset + 10] !== 0 ||
        bytes[offset + 11] !== 0 ||
        (bytes[offset + 12] !== 0 && bytes[offset + 12] !== 1)
    ) {
        malformed();
    }
    return { width: readU32BE(bytes, offset), height: readU32BE(bytes, offset + 4) };
}

function crc32(bytes: Uint8Array): number {
    let crc = 0xffffffff;
    for (let index = 0; index < bytes.length; index++) {
        crc = crc32Table[(crc ^ bytes[index]!) & 0xff]! ^ (crc >>> 8);
    }
    return (crc ^ 0xffffffff) >>> 0;
}

export type ImageDimensions = {
    height: number;
    width: number;
};

export type ProbedImage = ImageDimensions & {
    extension: string;
    mimeType: string;
};

import {
    ascii,
    exifOrientation,
    malformed,
    matches,
    readU16LE,
    readU24LE,
    readU32LE,
    requireBytes,
    unsupportedAnimation,
} from "./bytes.ts";
import type { ImageDimensions } from "./types.ts";

export function isWebp(bytes: Uint8Array): boolean {
    return bytes.length >= 12 && ascii(bytes, 0, 4) === "RIFF" && ascii(bytes, 8, 4) === "WEBP";
}

export function webpDimensions(bytes: Uint8Array): ImageDimensions {
    requireBytes(bytes, 0, 20);
    if (!isWebp(bytes) || readU32LE(bytes, 4) + 8 !== bytes.length) {
        malformed();
    }
    let offset = 12;
    let canvas: ImageDimensions | null = null;
    let frame: ImageDimensions | null = null;
    let orientation = 1;
    while (offset < bytes.length) {
        requireBytes(bytes, offset, 8);
        const kind = ascii(bytes, offset, 4);
        const length = readU32LE(bytes, offset + 4);
        const payload = offset + 8;
        requireBytes(bytes, payload, length);
        if (kind === "ANIM" || kind === "ANMF") {
            unsupportedAnimation();
        }
        if (kind === "EXIF") {
            orientation = exifOrientation(bytes.subarray(payload, payload + length)) ?? orientation;
        }
        if (kind === "VP8X") {
            if (canvas || length !== 10) {
                malformed();
            }
            if (bytes[payload]! & 0x02) {
                unsupportedAnimation();
            }
            canvas = {
                width: readU24LE(bytes, payload + 4) + 1,
                height: readU24LE(bytes, payload + 7) + 1,
            };
        } else if (kind === "VP8L" || kind === "VP8 ") {
            if (frame) {
                malformed();
            }
            frame =
                kind === "VP8L" ? losslessDimensions(bytes, payload, length) : lossyDimensions(bytes, payload, length);
        }
        offset = payload + length + (length % 2);
        requireBytes(bytes, 0, offset);
    }
    if (offset !== bytes.length || !frame) {
        malformed();
    }
    if (canvas && (canvas.width !== frame.width || canvas.height !== frame.height)) {
        malformed();
    }
    const dimensions = canvas ?? frame;
    return orientation >= 5 && orientation <= 8 ? { width: dimensions.height, height: dimensions.width } : dimensions;
}

function losslessDimensions(bytes: Uint8Array, payload: number, length: number): ImageDimensions {
    if (length < 5 || bytes[payload] !== 0x2f) {
        malformed();
    }
    const bits = readU32LE(bytes, payload + 1);
    return {
        width: (bits & 0x3fff) + 1,
        height: ((bits >>> 14) & 0x3fff) + 1,
    };
}

function lossyDimensions(bytes: Uint8Array, payload: number, length: number): ImageDimensions {
    if (length < 10 || !matches(bytes, payload + 3, [0x9d, 0x01, 0x2a])) {
        malformed();
    }
    return {
        width: readU16LE(bytes, payload + 6) & 0x3fff,
        height: readU16LE(bytes, payload + 8) & 0x3fff,
    };
}

import { HttpError } from "../../../core/errors.ts";
import { corsHeaders, json } from "../../../core/http.ts";
import { camelize, isRecord } from "../../../core/records.ts";
import { rpc } from "../../../core/rest.ts";
import type { JsonRecord } from "../../../core/types.ts";
import { productMediaBucket } from "./constants.ts";
import {
    productImagePath,
    readCommerceImage,
    readMediaIds,
    requiredQueryId,
    requireMediaUploadAuthorization,
} from "./request.ts";
import { deleteStorageImageBestEffort, downloadStorageImage, uploadStorageImageWithFailureCleanup } from "./storage.ts";

export async function uploadProductImage(request: Request): Promise<Response> {
    return attachUploadedImage(request, null);
}

export async function replaceProductImage(request: Request): Promise<Response> {
    return attachUploadedImage(request, requiredQueryId(request, "mediaId"));
}

export async function removeProductImage(request: Request): Promise<Response> {
    const result = await rpcRecord("remove_product_media", {
        p_product_id: requiredQueryId(request, "productId"),
        p_media_id: requiredQueryId(request, "mediaId"),
    });
    return resultResponse(result);
}

export async function reorderProductImages(request: Request): Promise<Response> {
    const result = await rpcRecord("reorder_product_media", {
        p_product_id: requiredQueryId(request, "productId"),
        p_media_ids: await readMediaIds(request),
    });
    return resultResponse(result);
}

export async function getProductImageFile(request: Request): Promise<Response> {
    const mediaId = requiredQueryId(request, "id", "mediaId");
    const context = await rpcRecord("get_product_media_download_context", {
        p_media_id: mediaId,
    });
    const media = context.state === "ok" && isRecord(context.media) ? context.media : null;
    if (!media || media.storage_bucket !== productMediaBucket || typeof media.storage_path !== "string") {
        throw new HttpError(404, "product image not found");
    }
    const stored = await downloadStorageImage(productMediaBucket, media.storage_path);
    const headers = new Headers(corsHeaders);
    copyHeader(stored, headers, "content-type", String(media.mime_type ?? "application/octet-stream"));
    copyHeader(stored, headers, "etag");
    copyHeader(stored, headers, "last-modified");
    headers.set("cache-control", "private, no-store");
    return new Response(stored.body, { status: 200, headers });
}

async function attachUploadedImage(request: Request, replacedMediaId: number | null): Promise<Response> {
    const productId = requiredQueryId(request, "productId");
    const authorization = await rpcRecord("authorize_product_media_upload", {
        p_product_id: productId,
        p_replace_media_id: replacedMediaId,
    });
    requireMediaUploadAuthorization(
        authorization,
        "product_id",
        productId,
        replacedMediaId,
        "authorize_product_media_upload",
    );
    const image = await readCommerceImage(request);
    const storagePath = productImagePath(productId, image);
    await uploadStorageImageWithFailureCleanup(productMediaBucket, storagePath, image.file);
    let result: JsonRecord;
    try {
        result = await rpcRecord("attach_product_media_v2", {
            p_product_id: productId,
            p_storage_bucket: productMediaBucket,
            p_storage_path: storagePath,
            p_mime_type: image.mimeType,
            p_file_size: image.file.size,
            p_original_filename: image.file.name || null,
            p_width: image.width,
            p_height: image.height,
            p_replace_media_id: replacedMediaId,
        });
    } catch (error) {
        if (isDefinitiveAttachRejection(error)) {
            await deleteStorageImageBestEffort(productMediaBucket, storagePath);
        }
        throw error;
    }
    return resultResponse(result);
}

function isDefinitiveAttachRejection(error: unknown): error is HttpError {
    return error instanceof HttpError && error.status >= 400 && error.status < 500;
}

async function rpcRecord(name: string, body: JsonRecord): Promise<JsonRecord> {
    const result = await rpc(name, body);
    if (!isRecord(result)) {
        throw new HttpError(502, `${name} returned an invalid response`);
    }
    return result;
}

function resultResponse(result: JsonRecord): Response {
    return json({ ok: true, ...(camelize(result) as JsonRecord) });
}

function copyHeader(source: Response, target: Headers, name: string, fallback?: string): void {
    const value = source.headers.get(name) ?? fallback;
    if (value) {
        target.set(name, value);
    }
}

import { HttpError } from "../../../core/errors.ts";
import { integer, readJsonObject } from "../../../core/records.ts";
import type { JsonRecord } from "../../../core/types.ts";
import { maxProductImageBytes } from "./constants.ts";
import { readSingleMultipartFile } from "./multipart.ts";
import { probeCommerceImage } from "./probe/index.ts";
import type { ProbedImage } from "./probe/index.ts";

export type CommerceImage = ProbedImage & {
    file: File;
};

export function requiredQueryId(request: Request, name: string, fallback?: string): number {
    const params = new URL(request.url).searchParams;
    const value = params.get(name) ?? (fallback ? params.get(fallback) : null);
    const id = integer(value, name, true)!;
    if (id <= 0) {
        throw new HttpError(400, `${name} must be positive`);
    }
    return id;
}

export async function readCommerceImage(request: Request): Promise<CommerceImage> {
    const multipart = await readSingleMultipartFile(request, maxProductImageBytes);
    const detected = probeCommerceImage(multipart.bytes);
    return {
        ...detected,
        file: new File([multipart.bytes], multipart.filename, {
            type: detected.mimeType,
        }),
    };
}

export function requireMediaUploadAuthorization(
    result: JsonRecord,
    ownerKey: "offer_id" | "product_id",
    ownerId: number,
    replaceMediaId: number | null,
    rpcName: string,
): void {
    if (result.state !== "authorized" || result[ownerKey] !== ownerId || result.replace_media_id !== replaceMediaId) {
        throw new HttpError(502, `${rpcName} returned an invalid authorization response`);
    }
}

export async function readMediaIds(request: Request): Promise<number[]> {
    const body = await readJsonObject(request);
    if (!Array.isArray(body.mediaIds)) {
        throw new HttpError(400, "mediaIds must be an array");
    }
    const ids = body.mediaIds.map((value, index) => {
        const id = integer(value, `mediaIds[${index}]`, true)!;
        if (id <= 0) {
            throw new HttpError(400, `mediaIds[${index}] must be positive`);
        }
        return id;
    });
    if (new Set(ids).size !== ids.length) {
        throw new HttpError(400, "mediaIds must be unique");
    }
    return ids;
}

export function productImagePath(productId: number, image: CommerceImage): string {
    return commerceImagePath("products", productId, image);
}

export function offerImagePath(offerId: number, image: CommerceImage): string {
    return commerceImagePath("offers", offerId, image);
}

function commerceImagePath(owner: "products" | "offers", ownerId: number, image: CommerceImage): string {
    const date = new Date().toISOString().slice(0, 10);
    return `${owner}/${ownerId}/${date}/${crypto.randomUUID()}${image.extension}`;
}

import { serviceRoleKey, requiredEnv } from "../../../core/env.ts";
import { HttpError } from "../../../core/errors.ts";
import { isRecord } from "../../../core/records.ts";

export async function uploadStorageImage(bucket: string, path: string, file: File): Promise<void> {
    const response = await storageObject(bucket, path, {
        method: "POST",
        headers: {
            "cache-control": "31536000",
            "content-type": file.type.toLowerCase(),
            "x-upsert": "false",
        },
        body: file,
    });
    if (!response.ok) {
        throw await storageError(response);
    }
}

export async function uploadStorageImageWithFailureCleanup(bucket: string, path: string, file: File): Promise<void> {
    try {
        await uploadStorageImage(bucket, path, file);
    } catch (error) {
        await deleteStorageImageBestEffort(bucket, path);
        throw error;
    }
}

export async function downloadStorageImage(bucket: string, path: string): Promise<Response> {
    const response = await storageObject(bucket, path, { method: "GET" });
    if (response.status === 404) {
        throw new HttpError(404, "product image not found");
    }
    if (!response.ok) {
        throw await storageError(response);
    }
    return response;
}

export async function deleteStorageImageBestEffort(bucket: string, path: string): Promise<void> {
    try {
        const response = await storageObject(bucket, path, { method: "DELETE" });
        if (!response.ok && response.status !== 404) {
            console.warn(`Unable to remove commerce media object (${response.status})`);
        }
    } catch (error) {
        console.warn("Unable to remove commerce media object", error);
    }
}

async function storageObject(bucket: string, path: string, init: RequestInit): Promise<Response> {
    const key = serviceRoleKey();
    const base = requiredEnv("SUPABASE_URL").replace(/\/$/, "");
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    if (key.startsWith("sb_")) {
        headers.delete("authorization");
    } else {
        headers.set("authorization", `Bearer ${key}`);
    }
    const bucketPath = encodeURIComponent(bucket);
    const objectPath = path.split("/").map(encodeURIComponent).join("/");
    return await fetch(`${base}/storage/v1/object/${bucketPath}/${objectPath}`, { ...init, headers });
}

async function storageError(response: Response): Promise<HttpError> {
    const body = await response.json().catch(() => null);
    const message =
        isRecord(body) && typeof body.message === "string"
            ? body.message
            : `Supabase Storage request failed (${response.status})`;
    return new HttpError(502, message);
}

import { camelize, isRecord, publicMetadata } from "../../../core/records.ts";
import type { JsonRecord } from "../../../core/types.ts";

export type ProductReadBundle = {
    product: JsonRecord;
    publicMetadataKeys: string[];
    axes: JsonRecord[];
    values: JsonRecord[];
    variants: JsonRecord[];
    selections: JsonRecord[];
    media: JsonRecord[];
    brand: JsonRecord | null;
    categories: JsonRecord[];
};

export function productData(bundle: ProductReadBundle, publicScope: boolean): JsonRecord {
    const product = publicScope
        ? {
              ...bundle.product,
              metadata: publicMetadata(bundle.product.metadata, new Set(bundle.publicMetadataKeys)),
          }
        : bundle.product;
    const currentVariants = matrixRows(
        bundle.axes,
        bundle.values,
        bundle.variants,
        bundle.selections,
        isRecord(product.metadata) ? product.metadata : {},
    );
    const mediaRows = bundle.media.map(mediaRow);
    const primaryCategory = bundle.categories.find((category) => category.is_primary === true) ?? null;
    return {
        ...(camelize(product) as JsonRecord),
        brand: bundle.brand ? camelize(bundle.brand) : null,
        primaryCategoryId: primaryCategory?.category_id ?? null,
        primaryCategory:
            primaryCategory && isRecord(primaryCategory.category) ? camelize(primaryCategory.category) : null,
        categories: bundle.categories.map((category) => camelize(category)),
        media: mediaRows,
        mainImageMediaId: mainMediaId(mediaRows),
        variantAxes: axisRows(bundle.axes, bundle.values),
        variants: currentVariants,
        variantMatrix: currentVariants,
    };
}

function axisRows(axes: JsonRecord[], values: JsonRecord[]): JsonRecord[] {
    return axes.map((axis) => ({
        key: axis.key,
        fieldKey: axis.field_key,
        label: axis.label,
        position: axis.position,
        values: values.filter((value) => same(value.axis_id, axis.id)).map((value) => value.label),
    }));
}

function matrixRows(
    axes: JsonRecord[],
    values: JsonRecord[],
    variants: JsonRecord[],
    selections: JsonRecord[],
    productMetadata: JsonRecord,
): JsonRecord[] {
    const axisById = new Map(axes.map((axis) => [String(axis.id), axis]));
    const valueById = new Map(values.map((value) => [String(value.id), value]));
    return variants.flatMap((variant) => {
        const choices = selections
            .filter((row) => same(row.variant_id, variant.id))
            .map((row) => {
                const axis = axisById.get(String(row.axis_id));
                const value = valueById.get(String(row.value_id));
                return axis && value
                    ? {
                          axisKey: axis.key,
                          axisLabel: axis.label,
                          valueKey: value.key,
                          valueLabel: value.label,
                          fieldKey: axis.field_key,
                          value: value.value,
                          position: axis.position,
                      }
                    : null;
            })
            .filter(isRecord)
            .sort((left, right) => Number(left.position) - Number(right.position));
        if (!variant.combination_key || choices.length !== axes.length) {
            return [];
        }
        return [
            {
                ...(camelize(variant) as JsonRecord),
                key: variant.combination_key,
                variantId: String(variant.id),
                options: choices.map((choice) => choice.valueLabel).join(" / "),
                choices: choices.map(({ position: _position, ...choice }) => choice),
                effectiveMetadata: {
                    ...productMetadata,
                    ...(isRecord(variant.metadata) ? variant.metadata : {}),
                    ...Object.fromEntries(
                        choices
                            .filter((choice) => choice.fieldKey)
                            .map((choice) => [String(choice.fieldKey), choice.value]),
                    ),
                },
            },
        ];
    });
}

function mediaRow(row: JsonRecord): JsonRecord {
    const media = isRecord(row.media) ? row.media : {};
    return camelize({ ...row, media: { ...media, url: "" } }) as JsonRecord;
}

function mainMediaId(rows: JsonRecord[]): string | null {
    const row = rows.find((item) => item.isMain) ?? rows[0];
    return row && isRecord(row.media) ? String(row.media.id ?? "") || null : null;
}

function same(left: unknown, right: unknown): boolean {
    return String(left) === String(right);
}

import { HttpError } from "../../../core/errors.ts";
import { json } from "../../../core/http.ts";
import { camelize, integer, publicMetadata, readJsonObject, text } from "../../../core/records.ts";
import { listRows, restJson } from "../../../core/rest.ts";
import type { JsonRecord } from "../../../core/types.ts";
import { productData } from "./data.ts";
import { getProductReadModel, upsertProductReadModel } from "./read-model.ts";
import { withVariantMatrix } from "../variants/matrix.ts";

const productSelect = "id,slug,title,description,brand_id,status,visibility,metadata,version,created_at,updated_at";

export async function listProducts(request: Request, admin: boolean): Promise<Response> {
    const url = new URL(request.url);
    const params = paging(url);
    params.set("select", productSelect);
    params.set("order", "updated_at.desc,id.desc");
    if (!admin) {
        params.set("status", "eq.active");
        params.set("visibility", "eq.public");
    } else {
        addEq(params, "status", url.searchParams.get("status"));
        addEq(params, "visibility", url.searchParams.get("visibility"));
    }
    addSearch(params, url.searchParams.get("q"), ["title", "slug"]);
    const { rows, total } = await listRows(`products?${params.toString()}`);
    const items = admin ? rows : await redactMetadata(rows, "product");
    return json({
        items: camelize(items),
        total,
        limit: Number(params.get("limit")),
        offset: Number(params.get("offset")),
    });
}

export async function getProduct(request: Request, admin: boolean): Promise<Response> {
    const url = new URL(request.url);
    if (admin && url.searchParams.get("id") === "__new__") {
        return json(newProduct());
    }
    const selector = productSelector(url);
    const bundle = await getProductReadModel(admin ? "admin" : "public", selector.id, selector.slug);
    if (!bundle) {
        throw new HttpError(404, "product not found");
    }
    return json(productData(bundle, !admin));
}

export async function upsertProduct(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const body = withVariantMatrix(await readJsonObject(request));
    const productId = optionalId(url.searchParams.get("id"));
    const expectedVersion = integer(body.expectedVersion, "expectedVersion", productId !== null);
    const bundle = await upsertProductReadModel(productId, body, expectedVersion);
    return json(productData(bundle, false));
}

function productSelector(url: URL): { id: number | null; slug: string | null } {
    const id = optionalId(url.searchParams.get("id"));
    const slug = text(url.searchParams.get("slug")) ?? null;
    if (id === null && !slug) {
        throw new HttpError(400, "id or slug is required");
    }
    return { id, slug: id === null ? slug : null };
}

async function redactMetadata(rows: JsonRecord[], entityType: string): Promise<JsonRecord[]> {
    const definitions = await restJson<JsonRecord[]>(
        `custom_field_definitions?select=key&entity_type=eq.${entityType}&public_readable=eq.true&enabled=eq.true`,
    );
    const allowed = new Set(definitions.map((row) => String(row.key)));
    return rows.map((row) => ({ ...row, metadata: publicMetadata(row.metadata, allowed) }));
}

function newProduct(): JsonRecord {
    return {
        id: null,
        slug: "",
        title: "",
        description: "",
        brandId: null,
        primaryCategoryId: null,
        status: "draft",
        visibility: "public",
