import { isPublishedSnapshotUrl, publishedPageContentHash, type PublishedPage } from "./published-page-snapshot.ts";
import { booleanValue, camelize, isRecord, readJsonObject, requiredText } from "../../../core/records.ts";
import { rpc } from "../../../core/rest.ts";
import type { JsonRecord } from "../../../core/types.ts";

export async function syncBuyerLegalDocuments(request: Request): Promise<Response> {
    const requestBody = await readJsonObject(request);
    const configuration = await parseConfiguration(requestBody);
    const result = await rpc("sync_buyer_legal_documents", {
        p_enabled: configuration.enabled,
        p_documents: configuration.documents,
        p_snapshot_origin: configuration.snapshotOrigin,
        p_actor_id: "cms-integration-sync",
    });
    return json(camelize(result));
}

async function parseConfiguration(
    body: JsonRecord,
): Promise<{ enabled: boolean; documents: JsonRecord[]; snapshotOrigin: string | null }> {
    let value: JsonRecord = body;
    if (body.configuration !== undefined) {
        if (typeof body.configuration !== "string" || body.configuration.length > 8_388_608) {
            throw new HttpError(400, "configuration must be a JSON string no larger than 8 MiB");
        }
        if (body.enabled !== undefined || body.documents !== undefined) {
            throw new HttpError(400, "configuration cannot be combined with enabled or documents");
        }
        try {
            const parsed: unknown = JSON.parse(body.configuration);
            if (!isRecord(parsed)) {
                throw new Error("not an object");
            }
            value = parsed;
        } catch {
            throw new HttpError(400, "configuration must contain a JSON object");
        }
    }
    const enabled = booleanValue(value.enabled, "enabled");
    if (enabled === undefined) {
        throw new HttpError(400, "enabled is required");
    }
    if (!Array.isArray(value.documents) || value.documents.length > 20) {
        throw new HttpError(400, "documents must be an array of at most 20 entries");
    }
    const documents = await Promise.all(value.documents.map(documentConfiguration));
    const contentBytes = documents.reduce((total, document) => {
        const page = document.page as JsonRecord;
        return total + new TextEncoder().encode(page.content as string).byteLength;
    }, 0);
    if (contentBytes > maximumAggregateContentBytes) {
        throw new HttpError(422, "legal document page content exceeds the aggregate 8 MiB limit");
    }
    const keys = documents.map((document) => document.key);
    if (new Set(keys).size !== keys.length) {
        throw new HttpError(400, "document keys must be unique");
    }
    if (enabled && !documents.length) {
        throw new HttpError(422, "enabled legal acceptance requires at least one document");
    }
    const origins = new Set(
        documents.map((document) => {
            const page = document.page as JsonRecord;
            return new URL(page.publishedSnapshotUrl as string).origin;
        }),
    );
    if (origins.size > 1) {
        throw new HttpError(422, "legal document pages must use the same CMS Delivery origin");
    }
    return { enabled, documents, snapshotOrigin: origins.values().next().value ?? null };
}

async function documentConfiguration(value: unknown, index: number): Promise<JsonRecord> {
    if (!isRecord(value)) {
        throw new HttpError(400, `documents[${index}] must be an object`);
    }
    const key = boundedText(value.key, `documents[${index}].key`, 80);
    if (!/^[a-z][a-z0-9_.-]{1,79}$/.test(key)) {
        throw new HttpError(422, `documents[${index}].key is invalid`);
    }
    const contexts = contextValues(value.contexts, index);
    if (!isRecord(value.page)) {
        throw new HttpError(422, `documents[${index}].page must be an object`);
    }
    const page = pageConfiguration(value.page, index);
    return {
        key,
        enabled: booleanValue(value.enabled, `documents[${index}].enabled`) ?? true,
        label: boundedText(value.label, `documents[${index}].label`, 200),
        consentText: boundedText(value.consentText, `documents[${index}].consentText`, 1000),
        contexts,
        page: {
            ...page,
            contentHash: await publishedPageContentHash(page),
            publishedSnapshotUrl: snapshotUrl(value.page.publishedSnapshotUrl, page.id, index),
        },
    };
}

function pageConfiguration(value: JsonRecord, index: number): PublishedPage {
    return {
        id: pageText(value.id, `documents[${index}].page.id`, 512),
        path: pagePath(value.path, index),
        title: pageText(value.title, `documents[${index}].page.title`, 500),
        description: pageText(value.description, `documents[${index}].page.description`, 1000, true),
        content: pageContent(value.content, index),
    };
}

function contextValues(value: unknown, index: number): string[] {
    if (!Array.isArray(value) || !value.length || value.length > supportedContexts.size) {
        throw new HttpError(422, `documents[${index}].contexts must be a non-empty array`);
    }
    const contexts = value.map((entry) => requiredText(entry, `documents[${index}].contexts[]`));
    if (new Set(contexts).size !== contexts.length || contexts.some((entry) => !supportedContexts.has(entry))) {
        throw new HttpError(422, `documents[${index}].contexts contains unsupported or duplicate values`);
    }
    return [...contexts].sort();
}

function boundedText(value: unknown, name: string, maximum: number): string {
    const result = requiredText(value, name);
    if (result.length > maximum) {
        throw new HttpError(422, `${name} is too long`);
    }
    return result;
}

function pagePath(value: unknown, index: number): string {
    const result = pageText(value, `documents[${index}].page.path`, 2048);
    if (!result.startsWith("/")) {
        throw new HttpError(422, `documents[${index}].page.path must start with /`);
    }
    return result;
}

function pageText(value: unknown, name: string, maximum: number, allowEmpty = false): string {
    if (typeof value !== "string" || value.length > maximum || (!allowEmpty && !value.trim())) {
        throw new HttpError(422, `${name} is invalid`);
    }
    return value;
}

function pageContent(value: unknown, index: number): string {
    if (typeof value !== "string" || !value.trim()) {
        throw new HttpError(422, `documents[${index}].page.content must be a non-empty string`);
    }
    if (new TextEncoder().encode(value).byteLength > 2_000_000) {
        throw new HttpError(422, `documents[${index}].page.content is too large`);
    }
    return value;
}

function snapshotUrl(value: unknown, pageId: string, index: number): string {
    if (typeof value !== "string" || value.length > 4_096 || !isPublishedSnapshotUrl(value, pageId)) {
        throw new HttpError(
            422,
            `documents[${index}].page.publishedSnapshotUrl is missing or is not a trusted CMS snapshot URL`,
        );
    }
    return value;
}

const supportedContexts = new Set([
    "buyer_checkout",
    "protected_payment",
    "direct_purchase",
    "negotiated_offer",
    "cart",
]);
const maximumAggregateContentBytes = 8_388_608;

import { HttpError } from "../../../core/errors.ts";
import { isRecord } from "../../../core/records.ts";
import type { JsonRecord } from "../../../core/types.ts";

const snapshotSchema = "cms-published-page-snapshot-v1";
const snapshotRoute = "/.cms/content/published-page-snapshot";
const maximumContentBytes = 2_000_000;
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const hashPattern = /^[a-f0-9]{64}$/;

export type PublishedPage = {
    id: string;
    path: string;
    title: string;
    description: string;
    content: string;
};

export type VerificationDocument = {
    key: string;
    versionId: string;
    pageId: string;
    publishedSnapshotUrl: string;
};

export type BuyerLegalVerificationContext = {
    enabled: boolean;
    paymentAlreadyCreated: boolean;
    approvedSnapshotOrigin: string | null;
    documents: VerificationDocument[];
};

export function isPublishedSnapshotUrl(value: string, pageId: string, approvedOrigin?: string): boolean {
    try {
        const url = new URL(value);
        return (
            isAllowedOrigin(url) &&
            (!approvedOrigin || url.origin === approvedOrigin) &&
            !url.username &&
            !url.password &&
            !url.hash &&
            url.pathname.endsWith(snapshotRoute) &&
            [...url.searchParams.keys()].every((key) => key === "id") &&
            url.searchParams.getAll("id").length === 1 &&
            url.searchParams.get("id") === pageId
        );
    } catch {
        return false;
    }
}

export function buyerLegalVerificationContext(value: unknown): BuyerLegalVerificationContext {
    if (!isRecord(value) || typeof value.enabled !== "boolean" || !Array.isArray(value.documents)) {
        unavailableSnapshot();
    }
    if (value.documents.length > 20) {
        unavailableSnapshot();
    }
    const approvedSnapshotOrigin =
        typeof value.approvedSnapshotOrigin === "string" ? value.approvedSnapshotOrigin : null;
    if (value.enabled && (!approvedSnapshotOrigin || !isAllowedOriginValue(approvedSnapshotOrigin))) {
        unavailableSnapshot();
    }
    return {
        enabled: value.enabled,
        paymentAlreadyCreated: value.paymentAlreadyCreated === true,
        approvedSnapshotOrigin,
        documents: value.documents.map((document) =>
            verificationDocument(document, approvedSnapshotOrigin ?? undefined),
        ),
    };
}

export function parsePublishedPageSnapshot(value: string): { page: PublishedPage; contentHash: string } {
    let parsed: unknown;
    try {
        parsed = JSON.parse(value);
    } catch {
        unavailableSnapshot();
    }
    if (!isRecord(parsed) || parsed.schema !== snapshotSchema || !isRecord(parsed.page)) {
        unavailableSnapshot();
    }
    const page = pageValue(parsed.page);
    if (typeof parsed.contentHash !== "string" || !hashPattern.test(parsed.contentHash)) {
        unavailableSnapshot();
    }
    return { page, contentHash: parsed.contentHash };
}

export function unavailableSnapshot(): never {
    throw new HttpError(409, "LEGAL_DOCUMENT_NOT_AVAILABLE");
}

function pageValue(value: JsonRecord): PublishedPage {
    const id = stringValue(value.id, 512);
    const path = stringValue(value.path, 2_048);
    const title = stringValue(value.title, 500);
    const description = stringValue(value.description, 1_000, true);
    const content = stringValue(value.content, Number.MAX_SAFE_INTEGER);
    if (!id || !path.startsWith("/") || !title.trim() || !content.trim()) {
        unavailableSnapshot();
    }
    if (new TextEncoder().encode(content).byteLength > maximumContentBytes) {
        unavailableSnapshot();
    }
    return { id, path, title, description, content };
}

function verificationDocument(value: unknown, approvedOrigin?: string): VerificationDocument {
    if (!isRecord(value)) {
        unavailableSnapshot();
    }
    const key = stringValue(value.key, 80);
    const versionId = stringValue(value.versionId, 36);
    const pageId = stringValue(value.pageId, 512);
    const publishedSnapshotUrl = stringValue(value.publishedSnapshotUrl, 4_096);
    if (
        !key ||
        !uuidPattern.test(versionId) ||
        !pageId ||
        !isPublishedSnapshotUrl(publishedSnapshotUrl, pageId, approvedOrigin)
    ) {
        unavailableSnapshot();
    }
    return { key, versionId, pageId, publishedSnapshotUrl };
}

function stringValue(value: unknown, maximum: number, allowEmpty = false): string {
    if (typeof value !== "string" || value.length > maximum || (!allowEmpty && !value)) {
        unavailableSnapshot();
    }
    return value;
}

function isAllowedOrigin(url: URL): boolean {
    return (
        url.protocol === "https:" ||
        (url.protocol === "http:" &&
            (url.hostname === "localhost" ||
                url.hostname.endsWith(".localhost") ||
                url.hostname === "127.0.0.1" ||
                url.hostname === "[::1]"))
    );
}

function isAllowedOriginValue(value: string): boolean {
    try {
        const url = new URL(value);
        return url.origin === value && isAllowedOrigin(url);
    } catch {
        return false;
    }
}

import type { JsonRecord } from "../../../core/types.ts";
import {
    isPublishedSnapshotUrl,
    parsePublishedPageSnapshot,
    unavailableSnapshot,
    type BuyerLegalVerificationContext,
    type PublishedPage,
    type VerificationDocument,
} from "./published-page-snapshot-validation.ts";

const maximumResponseBytes = 16_777_216;
const maximumAggregateContentBytes = 8_388_608;
const maximumConcurrentSnapshotFetches = 4;
const fetchTimeoutMilliseconds = 4_000;

export {
    buyerLegalVerificationContext,
    isPublishedSnapshotUrl,
} from "./published-page-snapshot-validation.ts";
export type {
    BuyerLegalVerificationContext,
    PublishedPage,
} from "./published-page-snapshot-validation.ts";

export async function publishedPageContentHash(page: PublishedPage): Promise<string> {
    const serialized = JSON.stringify({
        id: page.id,
        path: page.path,
        title: page.title,
        description: page.description,
        content: page.content,
    });
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(serialized));
    return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

export async function fetchVerifiedBuyerLegalDocuments(context: BuyerLegalVerificationContext): Promise<JsonRecord[]> {
    if (!context.enabled || context.paymentAlreadyCreated) {
        return [];
    }
    const results = new Array<JsonRecord>(context.documents.length);
    let nextIndex = 0;
    let contentBytes = 0;
    const worker = async (): Promise<void> => {
        while (nextIndex < context.documents.length) {
            const index = nextIndex++;
            const document = context.documents[index]!;
            const snapshot = await fetchPublishedPage(document);
            contentBytes += new TextEncoder().encode(snapshot.page.content).byteLength;
            if (contentBytes > maximumAggregateContentBytes) {
                unavailableSnapshot();
            }
            results[index] = {
                key: document.key,
                expectedVersionId: document.versionId,
                contentHash: snapshot.contentHash,
                page: snapshot.page,
            };
        }
    };
    await Promise.all(
        Array.from(
            {
                length: Math.min(maximumConcurrentSnapshotFetches, context.documents.length),
            },
            worker,
        ),
    );
    return results;
}

async function fetchPublishedPage(
    document: VerificationDocument,
): Promise<{ page: PublishedPage; contentHash: string }> {
    if (!isPublishedSnapshotUrl(document.publishedSnapshotUrl, document.pageId)) {
        unavailableSnapshot();
    }
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), fetchTimeoutMilliseconds);
    try {
        const response = await fetch(document.publishedSnapshotUrl, {
            headers: { accept: "application/json" },
            redirect: "error",
            signal: controller.signal,
        });
        if (!response.ok || !response.headers.get("content-type")?.toLowerCase().includes("application/json")) {
            unavailableSnapshot();
        }
        const value = parsePublishedPageSnapshot(await boundedText(response));
        if (value.page.id !== document.pageId || (await publishedPageContentHash(value.page)) !== value.contentHash) {
            unavailableSnapshot();
        }
        return value;
    } catch {
        unavailableSnapshot();
    } finally {
        clearTimeout(timeout);
    }
}

async function boundedText(response: Response): Promise<string> {
    const length = Number(response.headers.get("content-length"));
    if (Number.isFinite(length) && length > maximumResponseBytes) {
        unavailableSnapshot();
    }
    if (!response.body) {
        unavailableSnapshot();
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let size = 0;
    let result = "";
    while (true) {
        const chunk = await reader.read();
        if (chunk.done) {
            break;
        }
        size += chunk.value.byteLength;
        if (size > maximumResponseBytes) {
            await reader.cancel();
            unavailableSnapshot();
        }
        result += decoder.decode(chunk.value, { stream: true });
    }
    return result + decoder.decode();
}

import { HttpError } from "../../core/errors.ts";
import { booleanValue, integer, text } from "../../core/records.ts";
import type { JsonRecord } from "../../core/types.ts";

export function dynamicField(row: JsonRecord): JsonRecord {
    const rawOptions = Array.isArray(row.options) ? row.options : [];
    return {
        id: String(row.key),
        label: String(row.label),
        type: row.field_type === "enum" ? "string" : row.field_type,
        path: `metadata.${String(row.key)}`,
        section: `${String(row.entity_type)}CustomFields`,
        required: row.required === true,
        selfEditable: row.self_editable === true,
        adminEditable: row.admin_editable !== false,
        showInDashboardTable: row.show_in_dashboard_table === true,
        exposeToEditorSources: row.public_readable === true,
        ...(row.field_type === "enum"
            ? { options: rawOptions.map((value) => ({ value: String(value), label: String(value) })) }
            : {}),
    };
}

export function normalizeOptions(value: unknown): string[] {
    if (value === undefined || value === null || value === "") {
        return [];
    }
    const values = Array.isArray(value) ? value : typeof value === "string" ? value.split(",") : null;
    if (!values) {
        throw new HttpError(422, "options must be an array or comma-separated text");
    }
    return [...new Set(values.map((entry) => String(entry).trim()).filter(Boolean))].slice(0, 64);
}

export function setText(target: JsonRecord, key: string, value: unknown, lowercase = false): void {
    const result = text(value);
    if (result !== undefined) {
        target[key] = lowercase ? result.toLowerCase() : result;
    }
}

export function setBoolean(target: JsonRecord, key: string, value: unknown): void {
    const result = booleanValue(value, key);
    if (result !== undefined) {
        target[key] = result;
    }
}

export function setInteger(target: JsonRecord, key: string, value: unknown): void {
    const result = integer(value, key);
    if (result !== undefined) {
        target[key] = result;
    }
}

import { HttpError } from "../../core/errors.ts";
import { json } from "../../core/http.ts";
import { booleanValue, camelize, integer, readJsonObject, text } from "../../core/records.ts";
import { one, restJson, rpc } from "../../core/rest.ts";
import type { JsonRecord } from "../../core/types.ts";
import { dynamicField, normalizeOptions, setBoolean, setInteger, setText } from "./fields.ts";

const settingsSelect =
    "id,mode,default_currency,require_verified_seller,offer_moderation,price_policy,whole_unit_prices,product_image_min_count,product_image_max_count,offer_image_min_count,offer_image_max_count,auto_approve_price_in_range,require_final_price_approval,seller_can_publish,buyer_legal_acceptance_enabled,active_c2c_fee_policy_id,active_c2c_protection_policy_id,active_c2c_seller_risk_policy_id,version,created_at,updated_at";
const customFieldSelect =
    "entity_type,key,label,field_type,options,unit,required,self_editable,admin_editable,public_readable,show_in_dashboard_table,position,enabled,created_at,updated_at";

export async function getSettings(): Promise<Response> {
    const row = await one("settings", { id: "default" }, settingsSelect);
    if (!row) {
        throw new HttpError(500, "commerce settings are missing");
    }
    return json(camelize(row));
}

export async function updateSettings(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const expectedVersion = integer(body.expectedVersion, "expectedVersion", true)!;
    const payload: JsonRecord = {};
    setText(payload, "mode", body.mode);
    setText(payload, "defaultCurrency", body.defaultCurrency, true);
    setText(payload, "offerModeration", body.offerModeration);
    setText(payload, "pricePolicy", body.pricePolicy);
    setBoolean(payload, "wholeUnitPrices", body.wholeUnitPrices);
    setInteger(payload, "productImageMinCount", body.productImageMinCount);
    setInteger(payload, "productImageMaxCount", body.productImageMaxCount);
    setInteger(payload, "offerImageMinCount", body.offerImageMinCount);
    setInteger(payload, "offerImageMaxCount", body.offerImageMaxCount);
    setBoolean(payload, "requireVerifiedSeller", body.requireVerifiedSeller);
    setBoolean(payload, "autoApprovePriceInRange", body.autoApprovePriceInRange);
    setBoolean(payload, "requireFinalPriceApproval", body.requireFinalPriceApproval);
    setBoolean(payload, "sellerCanPublish", body.sellerCanPublish);
    if (!Object.keys(payload).length) {
        throw new HttpError(400, "at least one setting is required");
    }

    const result = await rpc("update_settings", {
        p_payload: payload,
        p_expected_version: expectedVersion,
    });
    return json(camelize(result));
}

export async function listCustomFields(request: Request, entityOverride?: string): Promise<Response> {
    const url = new URL(request.url);
    const entityType = entityOverride ?? text(url.searchParams.get("entityType"));
    const params = new URLSearchParams({ select: customFieldSelect, order: "entity_type.asc,position.asc,key.asc" });
    if (entityType) {
        params.set("entity_type", `eq.${entityType}`);
    }
    if (entityOverride) {
        params.set("enabled", "eq.true");
    }
    const rows = await restJson<JsonRecord[]>(`custom_field_definitions?${params.toString()}`);
    const items = rows.map((row) => ({
        ...(camelize(row) as JsonRecord),
        id: `${String(row.entity_type)}:${String(row.key)}`,
    }));
    return json({ fields: rows.map(dynamicField), items, total: rows.length });
}

export async function listCustomFieldSchema(request: Request): Promise<Response> {
    const entityType = text(new URL(request.url).searchParams.get("entityType"));
    if (!entityType || !["product", "variant", "seller", "offer", "order"].includes(entityType)) {
        throw new HttpError(422, "supported entityType is required");
    }
    return listCustomFields(request, entityType);
}

export async function getCustomField(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const identity = text(url.searchParams.get("id"))?.split(":");
    const entityType = text(url.searchParams.get("entityType")) ?? identity?.[0];
    const key = text(url.searchParams.get("key")) ?? identity?.[1];
    if (!key || key === "__new__") {
        return json({
            entityType: entityType ?? "offer",
            key: "",
            label: "",
            fieldType: "string",
            options: [],
            unit: "",
            required: false,
            selfEditable: false,
            adminEditable: true,
            publicReadable: false,
            showInDashboardTable: false,
            position: 0,
            enabled: true,
        });
    }
    if (!entityType || !key) {
        throw new HttpError(400, "entityType and key are required");
    }
    const row = await one("custom_field_definitions", { entity_type: entityType, key }, customFieldSelect);
    if (!row) {
        throw new HttpError(404, "custom field not found");
    }
    return json(camelize(row));
}

export async function upsertCustomField(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const entityType = text(body.entityType);
    const key = text(body.key);
    const label = text(body.label);
    const fieldType = text(body.fieldType) ?? "string";
    if (!entityType || !key || !label) {
        throw new HttpError(400, "entityType, key, and label are required");
    }
    if (!["product", "variant", "seller", "offer", "order"].includes(entityType)) {
        throw new HttpError(422, "unsupported custom field entity type");
    }
    if (!["string", "number", "boolean", "enum"].includes(fieldType)) {
        throw new HttpError(422, "unsupported custom field type");
    }
    const options = normalizeOptions(body.options);
    if (fieldType === "enum" && !options.length) {
        throw new HttpError(422, "enum fields require options");
    }
    if (fieldType !== "enum" && options.length) {
        throw new HttpError(422, "only enum fields may define options");
    }
    const unit = fieldType === "number" ? text(body.unit) : undefined;
    if (unit && unit.length > 32) {
        throw new HttpError(422, "unit cannot exceed 32 characters");
    }
    const required = booleanValue(body.required, "required") ?? false;
    const selfEditable = booleanValue(body.selfEditable, "selfEditable") ?? false;
    const adminEditable = booleanValue(body.adminEditable, "adminEditable") ?? true;
    if (required && ["seller", "order"].includes(entityType) && !selfEditable) {
        throw new HttpError(422, "required self-created entity fields must be self editable");
    }
    if (required && entityType === "offer" && (!selfEditable || !adminEditable)) {
        throw new HttpError(422, "required offer fields must be editable by sellers and administrators");
    }
    if (required && ["product", "variant"].includes(entityType) && !adminEditable) {
        throw new HttpError(422, "required catalogue fields must be admin editable");
    }
    const result = await rpc("upsert_custom_field", {
        p_entity_type: entityType,
        p_key: key,
        p_label: label,
        p_field_type: fieldType,
        p_options: options,
        p_required: required,
        p_self_editable: selfEditable,
        p_admin_editable: adminEditable,
        p_public_readable: booleanValue(body.publicReadable, "publicReadable") ?? false,
        p_show_in_dashboard_table: booleanValue(body.showInDashboardTable, "showInDashboardTable") ?? false,
        p_position: integer(body.position, "position") ?? 0,
        p_enabled: booleanValue(body.enabled, "enabled") ?? true,
        p_unit: unit,
    });
    return json(camelize(result));
}

export async function deleteCustomField(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const entityType = text(url.searchParams.get("entityType"));
    const key = text(url.searchParams.get("key"));
    if (!entityType || !key) {
        throw new HttpError(400, "entityType and key are required");
    }
