import { cmsUserId } from "../../core/auth.ts";
import { HttpError } from "../../core/errors.ts";
import { corsHeaders, json } from "../../core/http.ts";
import { camelize, isRecord } from "../../core/records.ts";
import { rpc } from "../../core/rest.ts";
import type { JsonRecord } from "../../core/types.ts";
import { productMediaBucket } from "../catalog/media/constants.ts";
import {
    offerImagePath,
    readCommerceImage,
    readMediaIds,
    requiredQueryId,
    requireMediaUploadAuthorization,
} from "../catalog/media/request.ts";
import {
    deleteStorageImageBestEffort,
    downloadStorageImage,
    uploadStorageImageWithFailureCleanup,
} from "../catalog/media/storage.ts";

type OfferMediaScope = "public" | "admin" | "self";

const downloadContextFunction = "get_offer_media_download_context";

export async function uploadOfferImage(request: Request, scope: OfferMediaScope): Promise<Response> {
    return attachUploadedImage(request, scope, null);
}

export async function replaceOfferImage(request: Request, scope: OfferMediaScope): Promise<Response> {
    return attachUploadedImage(request, scope, requiredQueryId(request, "mediaId"));
}

export async function removeOfferImage(request: Request, scope: OfferMediaScope): Promise<Response> {
    const result = await rpcRecord("remove_offer_media", {
        p_offer_id: requiredQueryId(request, "offerId"),
        p_media_id: requiredQueryId(request, "mediaId"),
        p_cms_user_id: scope === "self" ? cmsUserId(request) : null,
    });
    return resultResponse(result);
}

export async function reorderOfferImages(request: Request, scope: OfferMediaScope): Promise<Response> {
    const result = await rpcRecord("reorder_offer_media", {
        p_offer_id: requiredQueryId(request, "offerId"),
        p_media_ids: await readMediaIds(request),
        p_cms_user_id: scope === "self" ? cmsUserId(request) : null,
    });
    return resultResponse(result);
}

export async function getOfferImageFile(request: Request, scope: OfferMediaScope): Promise<Response> {
    const mediaId = requiredQueryId(request, "id", "mediaId");
    const context = await rpcRecord(downloadContextFunction, {
        p_scope: scope,
        p_media_id: mediaId,
        p_cms_user_id: scope === "self" ? cmsUserIdOrNull(request) : null,
    });
    const media = downloadMedia(context);
    if (media.storage_bucket !== productMediaBucket || typeof media.storage_path !== "string") {
        throw new HttpError(404, "offer image not found");
    }
    const stored = await downloadStorageImage(productMediaBucket, media.storage_path);
    const headers = new Headers(corsHeaders);
    copyHeader(stored, headers, "content-type", String(media.mime_type ?? "application/octet-stream"));
    copyHeader(stored, headers, "etag");
    copyHeader(stored, headers, "last-modified");
    headers.set("cache-control", scope === "public" ? "public, max-age=31536000, immutable" : "private, no-store");
    return new Response(stored.body, { status: 200, headers });
}

function downloadMedia(context: JsonRecord): JsonRecord {
    if (context.state === "settings_unavailable") {
        throw new HttpError(502, "commerce settings are unavailable");
    }
    if (context.state === "seller_unavailable") {
        throw new HttpError(404, "offer not found");
    }
    if (context.state === "identity_required") {
        throw new HttpError(401, "missing CMS user id");
    }
    if (context.state === "not_found") {
        throw new HttpError(404, "offer image not found");
    }
    if (context.state !== "ok" || !isRecord(context.media)) {
        throw new HttpError(502, `${downloadContextFunction} returned an invalid response`);
    }
    return context.media;
}

async function attachUploadedImage(
    request: Request,
    scope: OfferMediaScope,
    replacedMediaId: number | null,
): Promise<Response> {
    const offerId = requiredQueryId(request, "offerId");
    const cmsUser = scope === "self" ? cmsUserId(request) : null;
    const authorization = await rpcRecord("authorize_offer_media_upload", {
        p_offer_id: offerId,
        p_replace_media_id: replacedMediaId,
        p_cms_user_id: cmsUser,
    });
    requireMediaUploadAuthorization(
        authorization,
        "offer_id",
        offerId,
        replacedMediaId,
        "authorize_offer_media_upload",
    );
    const image = await readCommerceImage(request);
    const storagePath = offerImagePath(offerId, image);
    await uploadStorageImageWithFailureCleanup(productMediaBucket, storagePath, image.file);
    let result: JsonRecord;
    try {
        result = await rpcRecord("attach_offer_media_v2", {
            p_offer_id: offerId,
            p_storage_bucket: productMediaBucket,
            p_storage_path: storagePath,
            p_mime_type: image.mimeType,
            p_file_size: image.file.size,
            p_original_filename: image.file.name || null,
            p_width: image.width,
            p_height: image.height,
            p_replace_media_id: replacedMediaId,
            p_cms_user_id: cmsUser,
        });
    } catch (error) {
        if (isDefinitiveAttachRejection(error)) {
            await deleteStorageImageBestEffort(productMediaBucket, storagePath);
        }
        throw error;
    }
    return resultResponse(result);
}

function isDefinitiveAttachRejection(error: unknown): error is HttpError {
    return error instanceof HttpError && error.status >= 400 && error.status < 500;
}

function cmsUserIdOrNull(request: Request): string | null {
    return (request.headers.get("x-cms-user-id") ?? "").trim() || null;
}

async function rpcRecord(name: string, body: JsonRecord): Promise<JsonRecord> {
    const result = await rpc(name, body);
    if (!isRecord(result)) {
        throw new HttpError(502, `${name} returned an invalid response`);
    }
    return result;
}

function resultResponse(result: JsonRecord): Response {
    return json({ ok: true, ...(camelize(result) as JsonRecord) });
}
function copyHeader(source: Response, target: Headers, name: string, fallback?: string): void {
    const value = source.headers.get(name) ?? fallback;
    if (value) {
        target.set(name, value);
    }
}

import { HttpError } from "../../core/errors.ts";
import { one } from "../../core/rest.ts";

export async function requirePublicSeller(sellerId: string): Promise<void> {
    const [settings, seller] = await Promise.all([
        one("settings", { id: "default" }, "require_verified_seller"),
        one("sellers", { id: sellerId }, "verification_status"),
    ]);
    if (!settings) {
        throw new HttpError(502, "commerce settings are unavailable");
    }
    const status = String(seller?.verification_status ?? "");
    if (
        !seller ||
        ["rejected", "suspended"].includes(status) ||
        (settings.require_verified_seller === true && status !== "verified")
    ) {
        throw new HttpError(404, "offer not found");
    }
}

import { HttpError } from "../../../core/errors.ts";
import { json } from "../../../core/http.ts";
import { integer, isRecord } from "../../../core/records.ts";
import { rpc } from "../../../core/rest.ts";
import type { JsonRecord } from "../../../core/types.ts";

type ManagedOfferScope = "admin" | "self";

const managedFunctionName = "get_managed_offer_read_model";
const negotiationFunctionName = "get_offer_negotiation_context";
const negotiationContextFields = [
    "offer_id",
    "offer_slug",
    "offer_title",
    "offer_main_image_media_id",
    "offer_main_image_width",
    "offer_main_image_height",
    "seller_cms_user_id",
    "seller_display_name",
    "reference_amount",
    "currency",
    "whole_unit_prices",
    "publication_status",
    "availability",
] as const;

export async function getManagedOfferReadModel(
    request: Request,
    scope: ManagedOfferScope,
    offerId: number | null,
    slug: string | undefined,
): Promise<JsonRecord> {
    const result = await rpc(managedFunctionName, {
        p_scope: scope,
        p_offer_id: offerId,
        p_slug: offerId === null ? (slug ?? null) : null,
        p_cms_user_id: scope === "self" ? cmsUserIdOrNull(request) : null,
    });
    if (!isRecord(result) || typeof result.state !== "string") {
        throw invalidResponse(managedFunctionName);
    }
    if (result.state === "not_found") {
        throw new HttpError(404, "offer not found");
    }
    if (result.state === "identity_required" && scope === "self") {
        throw new HttpError(401, "missing CMS user id");
    }
    if (result.state !== "ok" || !isRecord(result.offer)) {
        throw invalidResponse(managedFunctionName);
    }
    return result.offer;
}

export async function getOfferNegotiationContext(request: Request): Promise<Response> {
    const offerId = integer(new URL(request.url).searchParams.get("offerId"), "offerId", true)!;
    const result = await rpc(negotiationFunctionName, { p_offer_id: offerId });
    if (!isRecord(result) || typeof result.state !== "string") {
        throw invalidResponse(negotiationFunctionName);
    }
    if (result.state === "not_found") {
        throw new HttpError(404, "offer not found");
    }
    if (result.state === "seller_not_found") {
        throw new HttpError(404, "seller not found");
    }
    if (result.state !== "ok") {
        throw invalidResponse(negotiationFunctionName);
    }
    return json(projectNegotiationContext(result.context));
}

function cmsUserIdOrNull(request: Request): string | null {
    return (request.headers.get("x-cms-user-id") ?? "").trim() || null;
}

function projectNegotiationContext(value: unknown): JsonRecord {
    const dimensionsAreInvalid =
        isInvalidDimension(value, "offer_main_image_width") ||
        isInvalidDimension(value, "offer_main_image_height") ||
        (isRecord(value) &&
            ((value.offer_main_image_width === null) !== (value.offer_main_image_height === null) ||
                (value.offer_main_image_media_id === null &&
                    (value.offer_main_image_width !== null || value.offer_main_image_height !== null))));
    if (
        !isRecord(value) ||
        negotiationContextFields.some((field) => !Object.hasOwn(value, field)) ||
        !Number.isSafeInteger(value.offer_id) ||
        typeof value.offer_slug !== "string" ||
        typeof value.offer_title !== "string" ||
        (value.offer_main_image_media_id !== null && !Number.isSafeInteger(value.offer_main_image_media_id)) ||
        dimensionsAreInvalid ||
        (value.seller_cms_user_id !== null && typeof value.seller_cms_user_id !== "string") ||
        typeof value.seller_display_name !== "string" ||
        (value.reference_amount !== null && !Number.isSafeInteger(value.reference_amount)) ||
        typeof value.currency !== "string" ||
        typeof value.whole_unit_prices !== "boolean" ||
        typeof value.publication_status !== "string" ||
        typeof value.availability !== "string"
    ) {
        throw invalidResponse(negotiationFunctionName);
    }
    return {
        offerId: value.offer_id,
        offerSlug: value.offer_slug,
        offerTitle: value.offer_title,
        offerMainImageMediaId: value.offer_main_image_media_id,
        offerMainImageWidth: value.offer_main_image_width,
        offerMainImageHeight: value.offer_main_image_height,
        sellerCmsUserId: value.seller_cms_user_id,
        sellerDisplayName: value.seller_display_name,
        referenceAmount: value.reference_amount,
        currency: value.currency,
        wholeUnitPrices: value.whole_unit_prices,
        publicationStatus: value.publication_status,
        availability: value.availability,
    };
}

function isInvalidDimension(value: unknown, field: "offer_main_image_width" | "offer_main_image_height"): boolean {
    if (!isRecord(value)) {
        return false;
    }
    const dimension = value[field];
    return dimension !== null && (!Number.isSafeInteger(dimension) || Number(dimension) <= 0);
}

function invalidResponse(functionName: string): HttpError {
    return new HttpError(502, `${functionName} returned an invalid response`);
}

import { HttpError } from "../../../core/errors.ts";
import { json } from "../../../core/http.ts";
import { camelize, integer, isRecord, text } from "../../../core/records.ts";
import { rpc } from "../../../core/rest.ts";
import type { JsonRecord } from "../../../core/types.ts";

export function hasContextualFilters(url: URL): boolean {
    return ["category", "brand", "filters"].some((name) => url.searchParams.has(name));
}

export async function listContextualOffers(url: URL): Promise<Response> {
    const limit = Math.min(Math.max(integer(url.searchParams.get("limit"), "limit") ?? 50, 1), 100);
    const offset = Math.max(integer(url.searchParams.get("offset"), "offset") ?? 0, 0);
    const result = await rpc("search_public_offers_read_model", {
        p_category_full_slug: text(url.searchParams.get("category")),
        p_brand_slug: text(url.searchParams.get("brand")),
        p_filters: parseFilters(url.searchParams.get("filters")),
        p_query: text(url.searchParams.get("q")),
        p_condition_code: text(url.searchParams.get("conditionCode")),
        p_price_min: amount(url.searchParams.get("priceMin")),
        p_price_max: amount(url.searchParams.get("priceMax")),
        p_sort: text(url.searchParams.get("sort")),
        p_limit: limit,
        p_offset: offset,
    });
    if (!isRecord(result) || !Array.isArray(result.items) || typeof result.whole_unit_prices !== "boolean") {
        throw new HttpError(502, "search_public_offers returned an invalid response");
    }
    const rows = result.items.filter(isRecord);
    return json({
        items: camelize(rows),
        wholeUnitPrices: result.whole_unit_prices,
        total: Number(result.total) || 0,
        limit,
        offset,
    });
}

function parseFilters(raw: string | null): JsonRecord {
    if (!raw) {
        return {};
    }
    if (raw.length > 16384) {
        throw new HttpError(400, "filters are too large");
    }
    let parsed: unknown;
    try {
        parsed = JSON.parse(raw);
    } catch {
        throw new HttpError(400, "filters must be valid JSON");
    }
    if (!isRecord(parsed)) {
        throw new HttpError(400, "filters must be an object");
    }
    return compactFilters(parsed);
}

function compactFilters(filters: JsonRecord): JsonRecord {
    return Object.fromEntries(
        Object.entries(filters).flatMap(([field, rawOperators]) => {
            if (!isRecord(rawOperators)) {
                return [[field, rawOperators]];
            }
            const operators = Object.fromEntries(
                Object.entries(rawOperators).filter(
                    ([, value]) =>
                        value !== "" &&
                        value !== null &&
                        value !== undefined &&
                        (!Array.isArray(value) || value.length > 0),
                ),
            );
            return Object.keys(operators).length > 0 ? [[field, operators]] : [];
        }),
    );
}

function amount(raw: string | null): number | null {
    if (!raw) {
        return null;
    }
    const euros = Number(raw);
    if (!Number.isFinite(euros) || euros < 0) {
        throw new HttpError(400, "price filter is invalid");
    }
    return Math.round(euros * 100);
}

import { json } from "../../../core/http.ts";
import { camelize, integer, text } from "../../../core/records.ts";
import { listRows } from "../../../core/rest.ts";
import { addFilter } from "../helpers.ts";
import { hasContextualFilters, listContextualOffers } from "./contextual-list.ts";
import { listPublicOfferReadModel } from "./public.ts";
import { listSellerOfferReadModel } from "./seller.ts";

const offerSelect =
    "id,seller_id,product_id,variant_id,slug,title,description,condition_code,publication_status,workflow_state,accepted_price_amount,currency,availability,quantity_available,metadata,version,created_at,updated_at";

export async function listOffers(request: Request, scope: "public" | "admin" | "self"): Promise<Response> {
    const url = new URL(request.url);
    if (scope === "public" && hasContextualFilters(url)) {
        return await listContextualOffers(url);
    }
    const limit = Math.min(Math.max(integer(url.searchParams.get("limit"), "limit") ?? 50, 1), 100);
    const offset = Math.max(integer(url.searchParams.get("offset"), "offset") ?? 0, 0);
    if (scope === "public") {
        return await listPublicOfferReadModel(url, limit, offset);
    }
    if (scope === "self") {
        return await listSellerOfferReadModel(request, url, limit, offset);
    }
    const params = new URLSearchParams({
        select: offerSelect,
        order: "updated_at.desc,id.desc",
        limit: String(limit),
        offset: String(offset),
    });
    addFilter(params, "publication_status", url.searchParams.get("publicationStatus"), true);
    addFilter(params, "workflow_state", url.searchParams.get("workflowState"), true);
    addFilter(params, "condition_code", url.searchParams.get("conditionCode"), true);
    addFilter(params, "product_id", url.searchParams.get("productId"), true);
    addFilter(params, "variant_id", url.searchParams.get("variantId"), true);
    addFilter(params, "seller_id", url.searchParams.get("sellerId"), true);
    const query = text(url.searchParams.get("q"))?.replace(/[,*()]/g, " ");
    if (query) {
        params.set("or", `(title.ilike.*${query}*,slug.ilike.*${query}*)`);
    }
    const { rows, total } = await listRows(`offers?${params.toString()}`);
