import { cmsUserId } from "../../../core/auth.ts";
import { HttpError } from "../../../core/errors.ts";
import { json } from "../../../core/http.ts";
import { integer, isRecord, text } from "../../../core/records.ts";
import { rpc } from "../../../core/rest.ts";
import type { JsonRecord } from "../../../core/types.ts";
import { parsePublicOrderMetadataDefinitions } from "../../../core/order-metadata.ts";
import { type DetailBundle, projectOrderDetail, projectSaleDetail } from "./detail-projection/index.ts";

type DetailScope = "buyer" | "seller" | "admin";

const functionName = "get_order_detail_read_model";
const optionalKeys = [
    "seller",
    "operation",
    "financial_terms",
    "fulfillment",
    "settlement",
    "claim",
    "authorization",
] as const;

export const getMyOrder = (request: Request): Promise<Response> => getOrderDetail(request, "buyer");
export const getAdminOrder = (request: Request): Promise<Response> => getOrderDetail(request, "admin");
export const getMySale = (request: Request): Promise<Response> => getOrderDetail(request, "seller");

async function getOrderDetail(request: Request, scope: DetailScope): Promise<Response> {
    const url = new URL(request.url);
    const id = integer(url.searchParams.get("id"), "id");
    const publicId = text(url.searchParams.get("publicId"));
    if (id === undefined && !publicId) {
        throw new HttpError(400, "id or publicId is required");
    }
    const actor = scope === "seller" ? cmsUserId(request) : scope === "buyer" ? cmsUserIdOrNull(request) : null;
    const result = await rpc(functionName, {
        p_scope: scope,
        p_cms_user_id: actor,
        p_id: id ?? null,
        p_public_id: id === undefined ? publicId! : null,
    });
    const bundle = readBundle(result, scope, actor);
    return json(scope === "seller" ? projectSaleDetail(bundle) : projectOrderDetail(bundle, scope === "buyer"));
}

function readBundle(value: unknown, scope: DetailScope, actor: string | null): DetailBundle {
    if (!isRecord(value) || typeof value.state !== "string") {
        throw invalidResponse();
    }
    if (value.state === "not_found") {
        throw new HttpError(404, scope === "seller" ? "sale not found" : "order not found");
    }
    if (value.state === "identity_required" && scope === "buyer" && actor === null) {
        throw new HttpError(401, "missing CMS user id");
    }
    if (value.state !== "ok" || !isRecord(value.order)) {
        throw invalidResponse();
    }
    const lines = recordArray(value.lines);
    const events = recordArray(value.events);
    const definitions = recordArray(value.definitions);
    if (!lines || !events || !definitions || optionalKeys.some((key) => value[key] !== null && !isRecord(value[key]))) {
        throw invalidResponse();
    }
    if (scope === "seller") {
        if (value.seller !== null || value.claim !== null) {
            throw invalidResponse();
        }
    } else if (value.authorization !== null) {
        throw invalidResponse();
    }
    if (scope === "admin" && definitions.length) {
        throw invalidResponse();
    }
    return {
        order: value.order,
        lines,
        events,
        seller: value.seller as JsonRecord | null,
        operation: value.operation as JsonRecord | null,
        financialTerms: value.financial_terms as JsonRecord | null,
        fulfillment: value.fulfillment as JsonRecord | null,
        settlement: value.settlement as JsonRecord | null,
        claim: value.claim as JsonRecord | null,
        authorization: value.authorization as JsonRecord | null,
        definitions: parsePublicOrderMetadataDefinitions(definitions),
    };
}

function recordArray(value: unknown): JsonRecord[] | null {
    return Array.isArray(value) && value.every(isRecord) ? value : null;
}

function cmsUserIdOrNull(request: Request): string | null {
    return (request.headers.get("x-cms-user-id") ?? "").trim() || null;
}

function invalidResponse(): HttpError {
    return new HttpError(502, `${functionName} returned an invalid response`);
}

import { HttpError } from "../../../core/errors.ts";
import { isRecord } from "../../../core/records.ts";
import { rpc } from "../../../core/rest.ts";

export type ClaimEvidenceActorKind = "buyer" | "seller";
export type ClaimEvidenceScope = ClaimEvidenceActorKind | "admin";

type DownloadContext =
    | { state: "identity_required" }
    | {
          state: "ok";
          evidence: {
              storageBucket: string;
              storagePath: string;
              mimeType: string | null;
          };
      };

const uploadFunction = "get_claim_evidence_upload_context";
const downloadFunction = "get_claim_evidence_download_context";
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export async function claimEvidenceUploadContext(
    claimId: number,
    actorKind: ClaimEvidenceActorKind,
    actorId: string,
): Promise<{ publicId: string }> {
    const value = await rpc(uploadFunction, {
        p_claim_id: claimId,
        p_actor_kind: actorKind,
        p_actor_id: actorId,
    });
    if (!isRecord(value) || typeof value.state !== "string") {
        throw invalid(uploadFunction);
    }
    if (value.state === "not_found") {
        throw new HttpError(404, "claim not found");
    }
    if (value.state !== "ok" || typeof value.public_id !== "string" || !uuidPattern.test(value.public_id)) {
        throw invalid(uploadFunction);
    }
    return { publicId: value.public_id };
}

export async function claimEvidenceDownloadContext(
    evidenceId: number,
    scope: ClaimEvidenceScope,
    actorId: string | null,
): Promise<DownloadContext> {
    const value = await rpc(downloadFunction, {
        p_evidence_id: evidenceId,
        p_scope: scope,
        p_actor_id: actorId,
    });
    if (!isRecord(value) || typeof value.state !== "string") {
        throw invalid(downloadFunction);
    }
    if (value.state === "evidence_not_found") {
        throw new HttpError(404, "claim evidence not found");
    }
    if (value.state === "claim_not_found") {
        throw new HttpError(404, "claim not found");
    }
    if (value.state === "identity_required") {
        if (scope === "admin" || actorId !== null) {
            throw invalid(downloadFunction);
        }
        return { state: "identity_required" };
    }
    if (value.state !== "ok" || !isRecord(value.evidence)) {
        throw invalid(downloadFunction);
    }
    const evidence = value.evidence;
    if (
        typeof evidence.storage_bucket !== "string" ||
        typeof evidence.storage_path !== "string" ||
        !isSafeStoragePath(evidence.storage_path) ||
        !(typeof evidence.mime_type === "string" || evidence.mime_type === null)
    ) {
        throw invalid(downloadFunction);
    }
    if (scope !== "admin" && actorId === null) {
        return { state: "identity_required" };
    }
    return {
        state: "ok",
        evidence: {
            storageBucket: evidence.storage_bucket,
            storagePath: evidence.storage_path,
            mimeType: evidence.mime_type,
        },
    };
}

function invalid(functionName: string): HttpError {
    return new HttpError(502, `${functionName} returned an invalid response`);
}

function isSafeStoragePath(path: string): boolean {
    const segments = path.split("/");
    return (
        segments[0] === "claims" &&
        segments.length > 1 &&
        segments.every((segment) => segment !== "" && segment !== "." && segment !== "..")
    );
}

import { cmsUserId } from "../../../core/auth.ts";
import { HttpError } from "../../../core/errors.ts";
