drop function if exists commerce.sync_buyer_legal_documents(
    boolean,
    jsonb,
    text
);
create or replace function commerce.sync_buyer_legal_documents(
    p_enabled boolean,
    p_documents jsonb,
    p_snapshot_origin text,
    p_actor_id text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_document jsonb;
    v_key text;
    v_label text;
    v_consent_text text;
    v_contexts text[];
    v_document_enabled boolean;
    v_enabled_document_count integer := 0;
    v_page_id text;
    v_page_path text;
    v_page_title text;
    v_page_description text;
    v_content jsonb;
    v_content_hash text;
    v_snapshot_url text;
    v_materialization_hash text;
begin
    if p_enabled is null then
        raise exception 'validation: enabled is required';
    end if;
    if p_actor_id is null
        or btrim(p_actor_id) = ''
        or length(p_actor_id) > 512 then
        raise exception 'forbidden: missing configuration actor';
    end if;
    if p_documents is null
        or jsonb_typeof(p_documents) <> 'array'
        or jsonb_array_length(p_documents) > 20
        or coalesce((
            select sum(octet_length(item->'page'->>'content'))
            from jsonb_array_elements(p_documents) item
        ), 0) > 8388608 then
        raise exception
            'validation: documents exceed count or aggregate content limits';
    end if;
    if jsonb_array_length(p_documents) > 0 and (
        p_snapshot_origin is null
        or length(p_snapshot_origin) > 2048
        or (
            p_snapshot_origin !~ '^https://[^/]+$'
            and p_snapshot_origin !~
                '^http://(localhost|[^/]+[.]localhost|127[.]0[.]0[.]1|[[]::1[]])(:[0-9]+)?$'
        )
    ) then
        raise exception
            'validation: legal document snapshot origin is invalid';
    end if;
    if exists (
        select 1
        from jsonb_array_elements(p_documents) item
        group by item->>'key'
        having count(*) > 1
    ) then
        raise exception
            'validation: legal document keys must be unique';
    end if;
    perform pg_advisory_xact_lock(
        hashtextextended('commerce:buyer-legal-documents', 0)
    );
    for v_document in
        select value from jsonb_array_elements(p_documents)
    loop
        select
            validated.document_key,
            validated.label,
            validated.consent_text,
            validated.checkout_contexts,
            validated.document_enabled,
            validated.page_id,
            validated.page_path,
            validated.page_title,
            validated.page_description,
            validated.page_content,
            validated.content_hash,
            validated.snapshot_url,
            validated.materialization_hash
        into
            v_key,
            v_label,
            v_consent_text,
            v_contexts,
            v_document_enabled,
            v_page_id,
            v_page_path,
            v_page_title,
            v_page_description,
            v_content,
            v_content_hash,
            v_snapshot_url,
            v_materialization_hash
        from commerce.validate_buyer_legal_sync_document(
            v_document,
            p_snapshot_origin
        ) validated;
        if v_document_enabled then
            v_enabled_document_count := v_enabled_document_count + 1;
        end if;
        perform commerce.materialize_buyer_legal_sync_document(
            v_key,
            v_document_enabled,
            v_label,
            v_consent_text,
            v_contexts,
            v_page_id,
            v_page_path,
            v_page_title,
            v_page_description,
            v_content,
            v_content_hash,
            v_snapshot_url,
            v_materialization_hash,
            p_actor_id
        );
    end loop;
    if p_enabled and v_enabled_document_count = 0 then
        raise exception
            'validation: enabled legal acceptance requires at least one enabled document';
    end if;
    update commerce.buyer_legal_documents configured
    set enabled = false, configured_by = p_actor_id
    where configured.enabled
      and not exists (
          select 1
          from jsonb_array_elements(p_documents) item
          where item->>'key' = configured.document_key
      );
    update commerce.settings
    set
        buyer_legal_acceptance_enabled = p_enabled,
        buyer_legal_snapshot_origin = case
            when jsonb_array_length(p_documents) > 0
                then p_snapshot_origin
            else null
        end
    where id = 'default'
      and (
          buyer_legal_acceptance_enabled,
          buyer_legal_snapshot_origin
      ) is distinct from (
          p_enabled,
          case
              when jsonb_array_length(p_documents) > 0
                  then p_snapshot_origin
              else null
          end
      );
    return jsonb_build_object(
        'enabled', p_enabled,
        'documents', coalesce((
            select jsonb_agg(jsonb_build_object(
                'key', document.document_key,
                'versionId', version.id,
                'contentHash', version.content_hash,
                'versionDate', version.materialized_at
            ) order by document.document_key)
            from commerce.buyer_legal_documents document
            join commerce.buyer_legal_document_versions version
              on version.id = document.current_version_id
            where document.enabled
        ), '[]'::jsonb)
    );
end;
$$;

create or replace function commerce.validate_buyer_legal_sync_document(
    p_document jsonb,
    p_snapshot_origin text
)
returns table (
    document_key text,
    label text,
    consent_text text,
    checkout_contexts text[],
    document_enabled boolean,
    page_id text,
    page_path text,
    page_title text,
    page_description text,
    page_content jsonb,
    content_hash text,
    snapshot_url text,
    materialization_hash text
)
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_page jsonb;
begin
    if jsonb_typeof(p_document) <> 'object' then
        raise exception 'validation: every legal document must be an object';
    end if;
    document_key := btrim(coalesce(p_document->>'key', ''));
    label := btrim(coalesce(p_document->>'label', ''));
    consent_text := btrim(coalesce(p_document->>'consentText', ''));
    v_page := p_document->'page';
    if p_document ? 'enabled'
        and jsonb_typeof(p_document->'enabled') <> 'boolean' then
        raise exception
            'validation: legal document enabled must be a boolean';
    end if;
    document_enabled := coalesce(
        (p_document->>'enabled')::boolean,
        true
    );
    if document_key !~ '^[a-z][a-z0-9_.-]{1,79}$' then
        raise exception 'validation: legal document key is invalid';
    end if;
    if label = '' or length(label) > 200 then
        raise exception 'validation: legal document label is invalid';
    end if;
    if consent_text = '' or length(consent_text) > 1000 then
        raise exception 'validation: legal document consent text is invalid';
    end if;
    if jsonb_typeof(p_document->'contexts') <> 'array' then
        raise exception
            'validation: legal document contexts must be an array';
    end if;
    select array_agg(distinct context order by context)
    into checkout_contexts
    from jsonb_array_elements_text(p_document->'contexts') context;
    if coalesce(cardinality(checkout_contexts), 0) = 0
        or not checkout_contexts <@ array[
            'buyer_checkout',
            'protected_payment',
            'direct_purchase',
            'negotiated_offer',
            'cart'
        ]::text[] then
        raise exception 'validation: legal document contexts are invalid';
    end if;
    if jsonb_typeof(v_page) <> 'object' or not v_page ? 'content' then
        raise exception
            'validation: legal document page snapshot is required';
    end if;
    page_id := coalesce(v_page->>'id', '');
    page_path := coalesce(v_page->>'path', '');
    page_title := coalesce(v_page->>'title', '');
    page_description := coalesce(v_page->>'description', '');
    page_content := v_page->'content';
    content_hash := coalesce(v_page->>'contentHash', '');
    snapshot_url := coalesce(v_page->>'publishedSnapshotUrl', '');
    if btrim(page_id) = '' or length(page_id) > 512 then
        raise exception 'validation: legal document page id is invalid';
    end if;
    if page_path !~ '^/' or length(page_path) > 2048 then
        raise exception 'validation: legal document page path is invalid';
    end if;
    if btrim(page_title) = '' or length(page_title) > 500 then
        raise exception 'validation: legal document page title is invalid';
    end if;
    if jsonb_typeof(v_page->'description') <> 'string'
        or length(page_description) > 1000 then
        raise exception
            'validation: legal document page description is invalid';
    end if;
    if jsonb_typeof(page_content) <> 'string'
        or btrim(coalesce(page_content #>> '{}', '')) = ''
        or pg_column_size(page_content) > 2097152 then
        raise exception 'validation: legal document page content is invalid';
    end if;
    if content_hash !~ '^[a-f0-9]{64}$'
        or content_hash <> commerce.buyer_legal_published_page_hash(
            page_id,
            page_path,
            page_title,
            page_description,
            page_content #>> '{}'
        ) then
        raise exception
            'validation: legal document content hash does not match its page snapshot';
    end if;
    if length(snapshot_url) > 4096
        or snapshot_url !~ '^https?://'
        or snapshot_url not like p_snapshot_origin || '/%'
        or snapshot_url !~
            '/[.]cms/content/published-page-snapshot[?]' then
        raise exception
            'validation: legal document snapshot URL is invalid';
    end if;
    materialization_hash := encode(extensions.digest(
        jsonb_build_object(
            'contentHash', content_hash,
            'label', label,
            'consentText', consent_text,
            'contexts', to_jsonb(checkout_contexts)
        )::text,
        'sha256'
    ), 'hex');
    return next;
end;
$$;

create or replace function commerce.update_settings(
    p_payload jsonb,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_enable_whole_unit_prices boolean;
    v_product_image_min_count integer;
    v_product_image_max_count integer;
    v_offer_image_min_count integer;
    v_offer_image_max_count integer;
begin
    select * into v_settings from commerce.settings where id = 'default' for update;
    if v_settings.version is distinct from p_expected_version then
        raise exception 'conflict: stale settings version';
    end if;
    v_enable_whole_unit_prices := coalesce(
        (p_payload->>'wholeUnitPrices')::boolean,
        v_settings.whole_unit_prices
    );
    v_product_image_min_count := coalesce(
        (p_payload->>'productImageMinCount')::integer,
        v_settings.product_image_min_count
    );
    v_product_image_max_count := coalesce(
        (p_payload->>'productImageMaxCount')::integer,
        v_settings.product_image_max_count
    );
    v_offer_image_min_count := coalesce(
        (p_payload->>'offerImageMinCount')::integer,
        v_settings.offer_image_min_count
    );
    v_offer_image_max_count := coalesce(
        (p_payload->>'offerImageMaxCount')::integer,
        v_settings.offer_image_max_count
    );
    if v_product_image_min_count < 0 or v_product_image_max_count > 20
        or v_product_image_min_count > v_product_image_max_count then
        raise exception 'validation: product image counts must satisfy 0 <= minimum <= maximum <= 20';
    end if;
    if v_offer_image_min_count < 0 or v_offer_image_max_count > 20
        or v_offer_image_min_count > v_offer_image_max_count then
        raise exception 'validation: offer image counts must satisfy 0 <= minimum <= maximum <= 20';
    end if;
    if v_enable_whole_unit_prices and not v_settings.whole_unit_prices and (
        exists (
            select 1 from commerce.offers
            where publication_status <> 'archived'
              and accepted_price_amount is not null
              and mod(accepted_price_amount, 100) <> 0
        )
        or exists (
            select 1
            from commerce.offer_price_rules rule
            join commerce.offers offer on offer.id = rule.offer_id
            where offer.publication_status <> 'archived'
              and (mod(rule.minimum_amount, 100) <> 0 or mod(rule.maximum_amount, 100) <> 0)
        )
        or exists (
            select 1
            from commerce.offer_price_proposals proposal
            join commerce.offers offer on offer.id = proposal.offer_id
            where offer.publication_status <> 'archived'
              and proposal.status in ('pending', 'accepted')
              and mod(proposal.amount, 100) <> 0
        )
    ) then
        raise exception 'conflict: non-whole offer prices must be resolved before enabling whole-unit prices';
    end if;
    update commerce.settings
    set mode = coalesce(nullif(p_payload->>'mode', ''), mode),
        default_currency = coalesce(nullif(lower(p_payload->>'defaultCurrency'), ''), default_currency),
        require_verified_seller = coalesce((p_payload->>'requireVerifiedSeller')::boolean, require_verified_seller),
        offer_moderation = coalesce(nullif(p_payload->>'offerModeration', ''), offer_moderation),
        price_policy = coalesce(nullif(p_payload->>'pricePolicy', ''), price_policy),
        whole_unit_prices = v_enable_whole_unit_prices,
        product_image_min_count = v_product_image_min_count,
        product_image_max_count = v_product_image_max_count,
        offer_image_min_count = v_offer_image_min_count,
        offer_image_max_count = v_offer_image_max_count,
        auto_approve_price_in_range = coalesce((p_payload->>'autoApprovePriceInRange')::boolean, auto_approve_price_in_range),
        require_final_price_approval = coalesce((p_payload->>'requireFinalPriceApproval')::boolean, require_final_price_approval),
        seller_can_publish = coalesce((p_payload->>'sellerCanPublish')::boolean, seller_can_publish)
    where id = 'default'
    returning * into v_settings;

    if v_settings.mode = 'ecommerce' then
        update commerce.offers offer
        set publication_status = 'paused'
        from commerce.sellers seller
        where seller.id = offer.seller_id
          and seller.kind = 'user'
          and offer.publication_status = 'active';
    end if;
    return to_jsonb(v_settings);
end;
$$;

