create or replace function commerce.review_marketplace_service_withdrawal_request(
    p_request_public_id uuid,
    p_next_status text,
    p_resolution text,
    p_actor_id text,
    p_note text,
    p_expected_version integer
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_request commerce.marketplace_service_withdrawal_requests%rowtype;
    v_previous_status text;
    v_actor text := nullif(btrim(p_actor_id), '');
    v_note text := nullif(btrim(p_note), '');
begin
    if p_request_public_id is null then
        raise exception 'validation: request public id is required';
    end if;
    if v_actor is null then
        raise exception 'forbidden: missing review actor';
    end if;
    if v_note is null or length(v_note) > 4000 then
        raise exception 'validation: review note is required and must not exceed 4000 characters';
    end if;
    if p_expected_version is null or p_expected_version <= 0 then
        raise exception 'validation: expected version is required';
    end if;
    if p_next_status not in ('under_review', 'information_requested', 'resolved') then
        raise exception 'validation: unsupported service withdrawal status';
    end if;
    if p_next_status = 'resolved' then
        if p_resolution is null or p_resolution not in ('accepted', 'rejected', 'no_action') then
            raise exception 'validation: a supported resolution is required';
        end if;
    elsif p_resolution is not null then
        raise exception 'validation: resolution is only allowed for a resolved request';
    end if;

    select * into v_request
    from commerce.marketplace_service_withdrawal_requests
    where public_id = p_request_public_id
    for update;
    if not found then
        raise exception 'not_found: service withdrawal request';
    end if;
    if v_request.version <> p_expected_version then
        raise exception 'conflict: stale service withdrawal request version';
    end if;
    if v_request.status = 'resolved' then
        raise exception 'conflict: service withdrawal request is already resolved';
    end if;
    if v_request.status = p_next_status then
        raise exception 'conflict: service withdrawal request status is unchanged';
    end if;

    v_previous_status := v_request.status;
    update commerce.marketplace_service_withdrawal_requests
    set
        status = p_next_status,
        resolution = case when p_next_status = 'resolved' then p_resolution else null end,
        last_reviewed_at = clock_timestamp(),
        last_reviewed_by = v_actor,
        review_note = v_note,
        version = version + 1,
        updated_at = clock_timestamp()
    where id = v_request.id
      and version = p_expected_version
    returning * into v_request;
    if not found then
        raise exception 'conflict: stale service withdrawal request version';
    end if;

    insert into commerce.marketplace_service_withdrawal_events (
        request_id, order_id, event_type, actor_kind, actor_id,
        previous_status, next_status, request_version, note, data
    ) values (
        v_request.id, v_request.order_id, 'reviewed', 'admin', v_actor,
        v_previous_status, v_request.status, v_request.version, v_note,
        jsonb_build_object('resolution', v_request.resolution)
    );
    perform commerce.append_financial_event(
        v_request.order_id,
        'marketplace_service_withdrawal_request',
        v_request.id::text,
        'service_withdrawal_reviewed',
        'admin',
        v_actor,
        v_note,
        jsonb_build_object(
            'previousStatus', v_previous_status,
            'nextStatus', v_request.status,
            'resolution', v_request.resolution,
            'requestVersion', v_request.version
        ),
        'commerce.marketplace_service_withdrawal.reviewed',
        'service-withdrawal:' || v_request.id || ':review:' || v_request.version
    );

    return commerce.marketplace_service_withdrawal_request_read_model(v_request.id);
end;
$$;

comment on function commerce.review_marketplace_service_withdrawal_request(
    uuid, text, text, text, text, integer
) is
    'CAS review decision only. Financial and order effects require independent authorized workflows.';

create or replace function commerce.review_order_cancellation_as(
    p_request_id bigint,
    p_decision text,
    p_actor_kind text,
    p_actor_id text,
    p_reason text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_request commerce.order_cancellation_requests%rowtype;
    v_order commerce.orders%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_refund jsonb;
    v_payment_cancellation jsonb;
begin
    if p_decision not in ('approved', 'rejected') then raise exception 'validation: unsupported cancellation decision'; end if;
    if p_actor_kind is null or p_actor_kind not in ('admin', 'system')
        or p_actor_id is null or length(btrim(p_actor_id)) = 0 then
        raise exception 'forbidden: cancellation review actor is not allowed';
    end if;
    select * into v_request from commerce.order_cancellation_requests where id = p_request_id for update;
    if not found then raise exception 'not_found: cancellation request'; end if;
    if v_request.status <> 'requested' then raise exception 'conflict: cancellation request is no longer reviewable'; end if;
    if p_decision = 'rejected' then
        update commerce.order_cancellation_requests set status = 'rejected', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        update commerce.orders set status = 'active' where id = v_request.order_id and status = 'cancellation_pending';
        perform commerce.append_financial_event(
            v_request.order_id, 'cancellation', v_request.id::text, 'cancellation_rejected',
            p_actor_kind, p_actor_id, p_reason, '{}'::jsonb,
            'commerce.order.cancellation_reviewed', 'cancellation:' || v_request.id || ':rejected'
        );
        return to_jsonb(v_request);
    end if;
    select * into v_order from commerce.orders where id = v_request.order_id for update;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = v_order.id order by created_at desc limit 1;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = v_order.id for update;
    if v_fulfillment.status in ('shipment_creating', 'label_created') then
        update commerce.order_cancellation_requests set
            status = 'provider_cancellation_pending', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        insert into commerce.shipment_cancellation_operations (
            order_id, order_cancellation_request_id, business_key, tracking_until
        ) values (
            v_order.id, v_request.id, 'shipment-cancellation:' || v_request.id,
            greatest(v_fulfillment.scan_grace_deadline, now() + interval '24 hours')
        ) on conflict (order_cancellation_request_id) do nothing;
        update commerce.orders set status = 'cancellation_pending' where id = v_order.id;
    elsif v_payment.status = 'succeeded' then
        v_refund := commerce.create_cancellation_refund_request(
            v_order.id, 'cancellation:' || v_request.id,
            'order_cancellation', p_actor_kind, p_actor_id
        );
        update commerce.order_cancellation_requests set
            status = 'refund_pending', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        update commerce.orders set status = 'cancellation_pending' where id = v_order.id;
    else
        update commerce.order_cancellation_requests set
            status = 'approved', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        v_payment_cancellation := commerce.ensure_payment_cancellation_request(
            v_order.id, 'cancelled', p_reason,
            'cancellation-review:' || v_request.id, v_request.id
        );
        select * into v_request from commerce.order_cancellation_requests where id = v_request.id;
    end if;
    perform commerce.append_financial_event(
        v_request.order_id, 'cancellation', v_request.id::text,
        'cancellation_' || v_request.status, p_actor_kind, p_actor_id, p_reason,
        jsonb_build_object('refundRequest', v_refund),
        'commerce.order.cancellation_reviewed', 'cancellation:' || v_request.id || ':' || v_request.status
    );
    return to_jsonb(v_request) || jsonb_build_object(
        'refundRequest', v_refund,
        'paymentCancellationAuthorization', v_payment_cancellation,
        'refundAuthorization', case when v_refund is null then null
            else commerce.refund_authorization_payload((v_refund->>'id')::bigint) end,
        'orderPublicId', v_order.public_id
    );
end;
$$;

create or replace function commerce.submit_marketplace_service_withdrawal_request(
    p_order_id bigint,
    p_buyer_cms_user_id text,
    p_service_scope text,
    p_reason text,
    p_confirmed boolean,
    p_idempotency_key text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
    v_buyer text := nullif(btrim(p_buyer_cms_user_id), '');
    v_scope text := btrim(coalesce(p_service_scope, ''));
    v_reason text := nullif(btrim(p_reason), '');
    v_key text := btrim(coalesce(p_idempotency_key, ''));
    v_confirmation_key constant text := 'marketplace_service_withdrawal_request.v1';
    v_request_hash text;
    v_existing commerce.marketplace_service_withdrawal_requests%rowtype;
    v_request commerce.marketplace_service_withdrawal_requests%rowtype;
    v_legal_snapshot jsonb;
    v_confirmed_at timestamptz := clock_timestamp();
begin
    if v_buyer is null then
        raise exception 'forbidden: missing CMS user id';
    end if;
    if p_order_id is null or p_order_id <= 0 then
        raise exception 'validation: order id must be positive';
    end if;
    if v_scope !~ '^[a-z][a-z0-9_.-]{1,79}$' then
        raise exception 'validation: invalid service scope';
    end if;
    if v_reason is not null and length(v_reason) > 4000 then
        raise exception 'validation: reason is too long';
    end if;
    if p_confirmed is not true then
        raise exception 'validation: explicit confirmation is required';
    end if;
    if length(v_key) not between 1 and 200 then
        raise exception 'validation: idempotency key is required and must not exceed 200 characters';
    end if;

    v_request_hash := encode(extensions.digest(pg_catalog.convert_to(
        jsonb_build_object(
            'orderId', p_order_id,
            'buyerCmsUserId', v_buyer,
            'serviceScope', v_scope,
            'reason', v_reason,
            'confirmationKey', v_confirmation_key
        )::text,
        'UTF8'
    ), 'sha256'), 'hex');

    perform pg_advisory_xact_lock(hashtextextended(
        'service-withdrawal:key:' || v_buyer || ':' || v_key, 0
    ));
    select * into v_existing
    from commerce.marketplace_service_withdrawal_requests
    where buyer_cms_user_id = v_buyer
      and idempotency_key = v_key;
    if found then
        if v_existing.request_hash <> v_request_hash then
            raise exception 'conflict: idempotency key was already used for another service withdrawal request';
        end if;
        return commerce.marketplace_service_withdrawal_request_read_model(v_existing.id)
            || jsonb_build_object('idempotent_replay', true);
    end if;

    perform 1
    from commerce.orders
    where id = p_order_id
      and buyer_cms_user_id = v_buyer;
    if not found then
        raise exception 'not_found: order';
    end if;

    perform pg_advisory_xact_lock(hashtextextended(
        'service-withdrawal:scope:' || p_order_id::text || ':' || v_scope, 0
    ));
    if exists (
        select 1
        from commerce.marketplace_service_withdrawal_requests
        where order_id = p_order_id
          and service_scope = v_scope
    ) then
        raise exception 'conflict: a service withdrawal request already exists for this order and scope';
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
        'acceptance_id', proof.id,
        'payment_attempt_id', proof.payment_attempt_id,
        'document_key', proof.document_key,
        'document_version_id', proof.document_version_id,
        'content_hash', proof.content_hash,
        'accepted_at', proof.accepted_at,
        'correlation_id', proof.correlation_id
    ) order by proof.document_key), '[]'::jsonb)
    into v_legal_snapshot
    from (
        select distinct on (acceptance.document_key)
            acceptance.id,
            acceptance.payment_attempt_id,
            acceptance.document_key,
            acceptance.document_version_id,
            acceptance.content_hash,
            acceptance.accepted_at,
            acceptance.correlation_id
        from commerce.order_buyer_legal_acceptances acceptance
        where acceptance.order_id = p_order_id
          and acceptance.buyer_cms_user_id = v_buyer
        order by acceptance.document_key, acceptance.accepted_at desc, acceptance.id desc
    ) proof;

    insert into commerce.marketplace_service_withdrawal_requests (
        order_id,
        buyer_cms_user_id,
        service_scope,
        reason,
        confirmation_key,
        confirmed_at,
        legal_acceptances_snapshot,
        idempotency_key,
        request_hash,
        submitted_at,
        updated_at
    ) values (
        p_order_id,
        v_buyer,
        v_scope,
        v_reason,
        v_confirmation_key,
        v_confirmed_at,
        v_legal_snapshot,
        v_key,
        v_request_hash,
        v_confirmed_at,
        v_confirmed_at
    ) returning * into v_request;

    insert into commerce.marketplace_service_withdrawal_events (
        request_id, order_id, event_type, actor_kind, actor_id,
        previous_status, next_status, request_version, data
    ) values (
        v_request.id, v_request.order_id, 'submitted', 'buyer', v_buyer,
        null, 'submitted', v_request.version,
        jsonb_build_object(
            'serviceScope', v_scope,
            'confirmationKey', v_confirmation_key,
            'legalAcceptanceCount', jsonb_array_length(v_legal_snapshot)
        )
    );
    perform commerce.append_financial_event(
        v_request.order_id,
        'marketplace_service_withdrawal_request',
        v_request.id::text,
        'service_withdrawal_submitted',
        'buyer',
        v_buyer,
        null,
        jsonb_build_object(
            'serviceScope', v_scope,
            'legalAcceptanceCount', jsonb_array_length(v_legal_snapshot)
        ),
        'commerce.marketplace_service_withdrawal.submitted',
        'service-withdrawal:' || v_request.id || ':submitted'
    );

    return commerce.marketplace_service_withdrawal_request_read_model(v_request.id)
        || jsonb_build_object('idempotent_replay', false);
end;
$$;

comment on function commerce.submit_marketplace_service_withdrawal_request(
    bigint, text, text, text, boolean, text
) is
    'Records evidence of an explicit buyer request. It never cancels an order or creates a refund.';

