definitions/configuration/theme.json.content:
{
    "categories": [
        {
            "id": "offer-cards",
            "label": "Offer cards",
            "description": "Theme defaults used by Commerce offer previews.",
            "tokens": [
                {
                    "id": "offer-accent",
                    "label": "Offer accent",
                    "type": "color",
                    "defaults": {
                        "light": "var(--primary-base)"
                    }
                },
                {
                    "id": "offer-background",
                    "label": "Offer background",
                    "type": "color",
                    "defaults": {
                        "light": "var(--bg-surface)"
                    }
                },
                {
                    "id": "offer-border",
                    "label": "Offer border",
                    "type": "color",
                    "defaults": {
                        "light": "var(--border-subtle, var(--border-default))"
                    }
                },
                {
                    "id": "offer-text",
                    "label": "Offer text",
                    "type": "color",
                    "defaults": {
                        "light": "var(--text-main)"
                    }
                },
                {
                    "id": "offer-muted-text",
                    "label": "Muted offer text",
                    "type": "color",
                    "defaults": {
                        "light": "var(--text-muted)"
                    }
                },
                {
                    "id": "offer-price",
                    "label": "Offer price",
                    "type": "color",
                    "defaults": {
                        "light": "var(--secondary-base)"
                    }
                },
                {
                    "id": "offer-radius",
                    "label": "Offer radius",
                    "type": "length",
                    "defaults": {
                        "light": "var(--radius-lg, var(--radius-card))"
                    }
                },
                {
                    "id": "offer-heading-font",
                    "label": "Offer heading font",
                    "type": "font-family",
                    "defaults": {
                        "light": "var(--font-display, var(--font-heading))"
                    }
                }
            ]
        }
    ]
}

